window.DATA = {"rules":[{"n":1,"title":"Verbi seguiti da to + verbo","items":[{"t":"exp","s":"Molti verbi reggono sempre “to” + verbo: want, try, ready, need, would like, hope, plan, decide, learn, forget, listen."},{"t":"wrong","s":"I want speak English  /  I’ll try explain it  /  I’m ready explain"},{"t":"right","s":"I want to speak  /  I’ll try to explain it  /  I’m ready to explain"}],"cat":"Verbi & tempi"},{"n":2,"title":"Aggettivi seguiti da to","items":[{"t":"exp","s":"Molti aggettivi reggono “to” + verbo: afraid, anxious, delighted, eager, glad, happy, pleased, ready, reluctant, sorry, surprised."},{"t":"wrong","s":"I’m happy help you  ·  she’s afraid ask"},{"t":"right","s":"I’m happy to help you  ·  she’s afraid to ask"}],"cat":"Verbi & tempi"},{"n":3,"title":"listen vs hear","items":[{"t":"exp","s":"Listen = ascoltare attivamente (podcast, musica). Hear = sentire passivamente, un suono che ti arriva."},{"t":"wrong","s":"a podcast I hear"},{"t":"right","s":"a podcast I listen to"}],"cat":"Parole che si confondono"},{"n":4,"title":"because vs why","items":[{"t":"exp","s":"Why = “perché?” come domanda. Because = “perché” come spiegazione."},{"t":"wrong","s":"it isn’t right why is for intermediate level"},{"t":"right","s":"it isn’t right because it’s for intermediate level"}],"cat":"Parole che si confondono"},{"n":5,"title":"what vs that (“che / quello che”)","items":[{"t":"exp","s":"what = “quello che / ciò che”, quando NON c’è un nome prima: I don’t know what you mean; repeat what she said."},{"t":"exp","s":"that = “che” pronome relativo, DOPO un nome (the book that I read; the man that called). Spesso si può togliere: the book I read."},{"t":"wrong","s":"repeat that she said  ·  the book what I read"},{"t":"right","s":"repeat what she said  ·  the book that I read"}],"cat":"Pronomi & possessivi"},{"n":6,"title":"is called (per i titoli)","items":[{"t":"exp","s":"Per il nome di un podcast, film o libro si usa “is called”. “Named” si usa più per persone o cose."},{"t":"wrong","s":"the podcast named Adept English"},{"t":"right","s":"the podcast is called Adept English"}],"cat":"Parole che si confondono"},{"n":7,"title":"who vs which","items":[{"t":"exp","s":"Per le persone si usa who. Which si usa solo per oggetti e cose."},{"t":"wrong","s":"a boyfriend which pays for everything"},{"t":"right","s":"a boyfriend who pays for everything"}],"cat":"Pronomi & possessivi"},{"n":8,"title":"talk about vs tell","items":[{"t":"exp","s":"Tell ha bisogno di una persona (tell me, tell us). Per un argomento si usa talk about o describe."},{"t":"wrong","s":"Hilary tells the trend"},{"t":"right","s":"Hilary talks about the trend"}],"cat":"Parole che si confondono"},{"n":9,"title":"her vs hers","items":[{"t":"exp","s":"Trucco: guarda cosa viene SUBITO DOPO il possessivo. Se c’è un nome → her. Se non c’è niente (la frase finisce lì) → hers."},{"t":"exp","s":"Non è la punteggiatura a decidere, ma se ripeti o no il nome. Hers sostituisce “her + nome” per non ripeterlo."},{"t":"exp","s":"È come my / mine:  her : hers = my : mine.  (her book → it’s hers,  come  my book → it’s mine)"},{"t":"wrong","s":"a credit card for hers shopping   ·   this book is her"},{"t":"right","s":"a credit card for her shopping   ·   this book is hers"}],"cat":"Pronomi & possessivi"},{"n":10,"title":"about · also · enough (posizione)","items":[{"t":"exp","s":"about → dopo il verbo, o in fondo alla frase relativa: what it’s about (non “what about is”)."},{"t":"exp","s":"also → prima del verbo principale, ma dopo il verbo to be: He also books… / He is also… (in fondo si usa too)."},{"t":"exp","s":"enough → dopo aggettivi/avverbi (good enough), ma prima dei nomi (enough time)."}],"cat":"Sintassi & frasi"},{"n":11,"title":"Non tradurre alla lettera (in this moment → right now)","items":[{"t":"exp","s":"Alcune espressioni tradotte parola per parola suonano innaturali."},{"t":"wrong","s":"in this moment"},{"t":"right","s":"right now / at the moment"},{"t":"wrong","s":"verily (antiquato, stile Shakespeare!)"},{"t":"right","s":"actually"},{"t":"wrong","s":"a little time"},{"t":"right","s":"a short time / a little bit"}],"cat":"Sintassi & frasi"},{"n":12,"title":"how = “come / il modo in cui”","items":[{"t":"exp","s":"Per dire “il modo in cui” si usa la struttura “This is how...”."},{"t":"wrong","s":"This is a baby learns to speak"},{"t":"right","s":"This is how a baby learns to speak"}],"cat":"Parole che si confondono"},{"n":13,"title":"every day vs everyday","items":[{"t":"exp","s":"every day (staccato) = ogni giorno (avverbio di tempo). everyday (attaccato) = quotidiano, ordinario (aggettivo davanti a un nome)."},{"t":"wrong","s":"I listen to a podcast everyday"},{"t":"right","s":"I listen to a podcast every day"}],"cat":"Parole che si confondono"},{"n":14,"title":"he / she + has (terza persona singolare)","items":[{"t":"exp","s":"Alla terza persona singolare (he, she, it) il verbo prende la -s: he has, she does. Per il passato è più semplice usare il past simple: what she said."},{"t":"wrong","s":"I don’t remember what he have said"},{"t":"right","s":"I don’t remember what she said  /  what she has said"}],"cat":"Verbi & tempi"},{"n":15,"title":"“da...” → for/since + present perfect","items":[{"t":"exp","s":"Regola d’oro: dove l’italiano usa il presente + “da”, l’inglese usa il present perfect + for/since. Significa che l’azione è iniziata nel passato e CONTINUA tuttora."},{"t":"exp","s":"for = durata (for 5 years).  since = punto di partenza (since 2010)."},{"t":"wrong","s":"She lives in Italy for several years  (presente semplice + durata = errore)"},{"t":"right","s":"She has lived in Italy for several years  (e ci vive ancora)"},{"t":"exp","s":"Attenzione al rovescio: past simple = finito. She lived in Italy for years = ci ha vissuto ma ora non più."},{"t":"exp","s":"Bonus — present perfect continuous (has/have been + -ing): stesso senso, ma sottolinea ancora di più che l’azione è in corso. She has been living in Italy for several years."}],"cat":"Verbi & tempi"},{"n":16,"title":"Present simple per le abitudini","items":[{"t":"exp","s":"Abitudini, routine e cose vere in generale → present simple. Segnalatori: always, usually, often, sometimes, never, every day/year."},{"t":"wrong","s":"Sometimes the two of us went to Greece  (se è un’abitudine attuale)"},{"t":"right","s":"Sometimes the two of us go to Greece"},{"t":"exp","s":"Se invece è un’abitudine finita nel passato, usa il past simple con un aggancio temporale: When we were younger, we sometimes went to Greece."}],"cat":"Verbi & tempi"},{"n":17,"title":"also / too / instead (riassunto)","items":[{"t":"exp","s":"ALSO = anche → aggiunge una cosa in più; va PRIMA del verbo (dopo il verbo to be). She also loves walking / She is also tired."},{"t":"exp","s":"TOO = anche → stesso senso di also, ma va IN FONDO alla frase. She loves walking too."},{"t":"exp","s":"Attenzione: also e too NON si usano insieme — scegline uno solo."},{"t":"wrong","s":"she also loves walking too"},{"t":"right","s":"she also loves walking  /  she loves walking too"},{"t":"exp","s":"INSTEAD = invece → sostituisce, mette una cosa AL POSTO di un’altra (instead, o instead of + nome/-ing). Non si usa per aggiungere."},{"t":"wrong","s":"She loves piano, instead she loves walking  (stai aggiungendo, non sostituendo)"},{"t":"right","s":"She doesn’t drive; she takes the train instead  /  Instead of driving, she walks"},{"t":"exp","s":"Per CONTRAPPORRE due cose o persone (non sostituirle) usa: but (ma), while / whereas (mentre), on the other hand (d’altra parte)."},{"t":"right","s":"Elena and her son both love the piano, but Elena is the only one who also loves walking"},{"t":"exp","s":"INSTEAD può anche iniziare una frase nuova (= “invece, al posto di ciò appena detto”): non serve “but” prima, ma serve un PUNTO o un PUNTO E VIRGOLA prima, mai solo la virgola (altrimenti è una “virgola a catena”)."},{"t":"wrong","s":"Everyone can fly, instead Tahani suggests cleaning the city (virgola a catena)"},{"t":"right","s":"Everyone can fly. Instead, Tahani suggests cleaning the city.  /  Everyone can fly; instead, Tahani suggests cleaning the city."}],"cat":"Sintassi & frasi"},{"n":18,"title":"La preposizione TO (luoghi e “married”)","items":[{"t":"exp","s":"Movimento verso un luogo → to: return to Italy, go back to Greece, travel to London. Non “in”."},{"t":"exp","s":"Sposarsi con qualcuno → married TO (non with): She’s married to Frank."},{"t":"exp","s":"go back = torni dove NON sei ora; come back = torni dove sei tu adesso."},{"t":"wrong","s":"married with Frank  ·  returned in Italy  ·  come back in Greece"},{"t":"right","s":"married to Frank  ·  returned to Italy  ·  go back to Greece"}],"cat":"Preposizioni"},{"n":19,"title":"Due frasi complete → punto, non virgola","items":[{"t":"exp","s":"In inglese due frasi che stanno in piedi da sole non si uniscono con la virgola: usa il punto o il punto e virgola (;)."},{"t":"wrong","s":"She works in a factory, her job is quality assurance"},{"t":"right","s":"She works in a factory; her job is quality assurance"}],"cat":"Sintassi & frasi"},{"n":20,"title":"think OF / think ABOUT (non “think to”)","items":[{"t":"exp","s":"“Pensare a” non si traduce con think to (calco dall’italiano). Si usa think of oppure think about."},{"t":"wrong","s":"we could think to food"},{"t":"right","s":"we might think of / about food"}],"cat":"Preposizioni"},{"n":21,"title":"modale + BE + participio (passivo)","items":[{"t":"exp","s":"Con i modali (must, can, should, will...) il passivo si fa con be + participio passato."},{"t":"wrong","s":"which must not advertised before 9 p.m."},{"t":"right","s":"which must not be advertised before 9 p.m."}],"cat":"Verbi & tempi"},{"n":22,"title":"it’s vs its","items":[{"t":"exp","s":"it’s = it is (o it has). its = suo/sua (possessivo, senza apostrofo). Non confonderli."},{"t":"wrong","s":"its responsible for obesity"},{"t":"right","s":"it’s responsible / they’re responsible for obesity"}],"cat":"Pronomi & possessivi"},{"n":23,"title":"must not vs should not","items":[{"t":"exp","s":"must not = non deve (divieto forte). should not / shouldn’t = non dovrebbe (consiglio). “Dovrebbe” si traduce con should."},{"t":"wrong","s":"This food must not be advertised  (se volevi dire “non dovrebbe”)"},{"t":"right","s":"This food shouldn’t be advertised"}],"cat":"Verbi & tempi"},{"n":24,"title":"Quantificatori (schema): some/any · much/many · a few/a little","items":[{"t":"exp","s":"PASSO 1 — guarda la FRASE: affermativa → some; negativa → any; domanda → any (se ti aspetti una risposta positiva, o è un’offerta/richiesta → some: Would you like some coffee?)."},{"t":"exp","s":"PASSO 2 — guarda la QUANTITÀ e il tipo di nome. NUMERABILI (cats): molti = many / a lot of; alcuni = a few. NON NUMERABILI (water): molto = much / a lot of; un po’ = a little."},{"t":"exp","s":"Con “a” (a few, a little) = tono positivo, “ce n’è”. Senza “a” (few, little) = pochi/poco, scarsità."},{"t":"exp","s":"Ricorda: much/many da soli soprattutto in negative e domande (nelle affermative meglio a lot of); i non numerabili non hanno plurale e vogliono il verbo singolare (there is water)."},{"t":"exp","s":"Schema visivo a colpo d’occhio: file “Schema_quantificatori.html” nella cartella."},{"t":"wrong","s":"There are much cars · How many sugar? · I don’t have some time"},{"t":"right","s":"There are many cars · How much sugar? · I don’t have any time"}],"cat":"Nomi, articoli & quantità"},{"n":25,"title":"comparativo e superlativo","items":[{"t":"exp","s":"Aggettivi corti: -er … than / the -est (big → bigger than → the biggest; cold → the coldest)."},{"t":"exp","s":"Aggettivi lunghi: more … than / the most (interesting → more interesting → the most interesting). Mai “more big”."},{"t":"exp","s":"Irregolari: good → better → the best;  bad → worse → the worst."},{"t":"wrong","s":"Rome is more big than Florence  ·  the most easy exercise"},{"t":"right","s":"Rome is bigger than Florence  ·  the easiest exercise"},{"t":"exp","s":"than serve solo se nomini il secondo termine. Se è sottinteso, comparativo senza than: This one is cheaper. / I feel better today. (than = con la a; dopo than: me/her/him)."},{"t":"exp","s":"Con i gruppi/luoghi il superlativo vuole in: the tallest in the family, the best in the world. E “tutta la famiglia” = the whole family (non “the all family”)."}],"cat":"Aggettivi & confronti"},{"n":26,"title":"età delle persone: older / younger","items":[{"t":"exp","s":"Per l’ETÀ si usa older (più grande) e younger (più piccolo); the oldest / the youngest. Bigger e smaller riguardano la TAGLIA fisica, non l’età."},{"t":"wrong","s":"a sister bigger than me  ·  he’s the smallest (= ultimo nato)"},{"t":"right","s":"a sister older than me  ·  he’s the youngest"},{"t":"exp","s":"Esistono big sister / little sister come espressioni fisse (sorella maggiore/minore), ma “bigger/smaller than” torna a indicare la taglia."}],"cat":"Aggettivi & confronti"},{"n":27,"title":"one / ones = sostituto di un nome","items":[{"t":"exp","s":"one sostituisce un nome numerabile già detto, per non ripeterlo (ones al plurale): the red one, the second one, these ones. Va bene se è chiaro a cosa si riferisce."},{"t":"right","s":"I have three children; I’m the second one  /  the second child  /  the second of three"}],"cat":"Pronomi & possessivi"},{"n":28,"title":"one’s: i tre usi","items":[{"t":"exp","s":"1) Nei modi di dire è un SEGNAPOSTO per il possessivo giusto (my/your/his/her...): to do one’s best → I do my best; to change one’s mind → she changed her mind."},{"t":"exp","s":"2) Possessivo del “one” impersonale (= proprio, formale): One should look after one’s health. Nel parlato → your."},{"t":"exp","s":"3) Contrazione di one is / one has: this one’s better (= is), the blue one’s gone (= has)."},{"t":"exp","s":"Trucco: dopo one’s c’è un nome → possessivo/segnaposto (one’s parents). C’è aggettivo/“got”/participio → one is / one has (this one’s ready)."}],"cat":"Pronomi & possessivi"},{"n":29,"title":"possessivo + superlativo: niente “the”","items":[{"t":"exp","s":"Non si usano due determinanti insieme: il possessivo (my/your/his...) e l’articolo (the/a) si escludono. Il possessivo sostituisce l’articolo, anche col superlativo."},{"t":"wrong","s":"my the oldest sister  ·  my the best friend"},{"t":"right","s":"my oldest sister  ·  my best friend  (oppure: the oldest sister)"}],"cat":"Aggettivi & confronti"},{"n":30,"title":"fun vs funny (falso amico)","items":[{"t":"exp","s":"fun = divertente, piacevole. funny = buffo, comico (che fa ridere). “Divertente” di solito è fun, non funny."},{"t":"wrong","s":"The holiday was very funny  (se intendi “divertente”)"},{"t":"right","s":"The holiday was a lot of fun  /  really fun"}],"cat":"Parole che si confondono"},{"n":31,"title":"niente doppia negazione","items":[{"t":"exp","s":"In inglese si usa UNA sola negazione. Non “didn’t never”, non “don’t nothing”."},{"t":"wrong","s":"I didn’t never wash the windows"},{"t":"right","s":"I never washed the windows  /  I didn’t ever wash the windows"}],"cat":"Sintassi & frasi"},{"n":32,"title":"home: stato in luogo vs movimento","items":[{"t":"exp","s":"STATO (dove SEI) → **at home** = “a casa”: I’m at home; I stay at home; she works at home."},{"t":"exp","s":"MOVIMENTO (dove VAI) → go / come / return / get **home**, SENZA preposizione: “tornare a casa” = return home (non “return at home”). L’italiano usa “a”, l’inglese niente."},{"t":"wrong","s":"I returned at home  ·  I go to home"},{"t":"right","s":"(movimento) I returned home  ·  I get home  —  (stato) I’m at home"}],"cat":"Preposizioni"},{"n":33,"title":"last month / on holiday","items":[{"t":"exp","s":"last e next + week/month/year vanno senza articolo (last month, next year). E si va ON holiday / ON vacation, non “to holiday”."},{"t":"wrong","s":"The last month  ·  went to holiday"},{"t":"right","s":"Last month  ·  went on holiday"}],"cat":"Preposizioni"},{"n":34,"title":"past simple: verbi irregolari comuni","items":[{"t":"exp","s":"go→went, be→was/were, have→had, do→did, buy→bought, sleep→slept, swim→swam, run→ran, wake→woke, come→came, eat→ate, see→saw, take→took, give→gave, read→read."},{"t":"wrong","s":"I runned  ·  I waked up"},{"t":"right","s":"I ran  ·  I woke up"}],"cat":"Verbi & tempi"},{"n":35,"title":"there are X of us (siamo in X)","items":[{"t":"exp","s":"Per dire quanti siete si usa there is/are + numero + of us/them/you (al passato there were), non “we are X”. of us = “di noi”."},{"t":"wrong","s":"We are nine (people)"},{"t":"right","s":"There are nine of us  /  There were nine of us"},{"t":"exp","s":"Se nomini il gruppo, usa numero + of + the/my/these + nome. Dopo of ci vuole SEMPRE un determinante (the, my, these): non “three of children”."},{"t":"wrong","s":"three of children"},{"t":"right","s":"three of the children  ·  two of my sisters  ·  many of my friends"},{"t":"exp","s":"Numero “secco”, in generale (non selezioni da un gruppo) → niente of, nome diretto: Nine people came to the party."}],"cat":"Sintassi & frasi"},{"n":36,"title":"ordine parole: aggettivo prima del nome","items":[{"t":"exp","s":"In inglese l’aggettivo va SEMPRE prima del nome: a fun vacation, a beautiful island, an old car. Non “a vacation fun”."},{"t":"wrong","s":"a vacation very fun  ·  a car red"},{"t":"right","s":"a very fun vacation  ·  a red car"},{"t":"exp","s":"E il soggetto non si omette mai: Last year WE went to Greece (non “Last year went…”)."}],"cat":"Sintassi & frasi"},{"n":37,"title":"past simple: domande e negazioni (did + base)","items":[{"t":"exp","s":"Nel passato, domande e negazioni si fanno con did / didn’t + verbo alla forma BASE. Il “did” porta già il passato, quindi il verbo NON va al passato."},{"t":"wrong","s":"Do you have a good time? (per il passato)  ·  I didn’t went"},{"t":"right","s":"Did you have a good time?  ·  I didn’t go"}],"cat":"Verbi & tempi"},{"n":38,"title":"plurali irregolari","items":[{"t":"exp","s":"Alcuni plurali non prendono -s: mouse→mice, child→children, man→men, woman→women, foot→feet, tooth→teeth, person→people."},{"t":"wrong","s":"little mouses  ·  two childs"},{"t":"right","s":"little mice  ·  two children"}],"cat":"Nomi, articoli & quantità"},{"n":39,"title":"l’età: X years old","items":[{"t":"exp","s":"Per l’età si dice “X years old” (o l’aggettivo “a X-year-old…”, con i trattini e year al singolare)."},{"t":"wrong","s":"a cat 3 years  ·  a 3 years old cat"},{"t":"right","s":"a cat 3 years old  ·  a 3-year-old cat"}],"cat":"Aggettivi & confronti"},{"n":40,"title":"l’articolo a / an","items":[{"t":"exp","s":"Davanti a un nome numerabile singolare ci vuole a/an: a cat, an apartment. an prima di suono vocalico (an apple, an hour), a prima di consonante (a house)."},{"t":"wrong","s":"lives in apartment  ·  she has cat"},{"t":"right","s":"lives in an apartment  ·  she has a cat"}],"cat":"Nomi, articoli & quantità"},{"n":41,"title":"non numerabili → verbo al singolare","items":[{"t":"exp","s":"I nomi non numerabili (milk, water, money, information, advice, news) vogliono il verbo al SINGOLARE e non hanno plurale: There is milk. The news is good. Information is useful."},{"t":"wrong","s":"There are a little milk · informations · the news are good"},{"t":"right","s":"There is a little milk · information · the news is good"}],"cat":"Nomi, articoli & quantità"},{"n":42,"title":"little / a little · few / a few (l’articolo cambia il senso)","items":[{"t":"exp","s":"CON “a”: a little / a few = “un po’” / “alcuni”, tono positivo (ce n’è). SENZA “a”: little / few = “poco” / “pochi”, tono negativo di scarsità (quasi niente), più formale."},{"t":"right","s":"I have a few friends (alcuni)  ·  I have few friends (pochi, quasi nessuno)"},{"t":"right","s":"We have a little time (un po’)  ·  We have little time (poco)"}],"cat":"Nomi, articoli & quantità"},{"n":43,"title":"much / many nelle affermative → a lot of","items":[{"t":"exp","s":"much e many da soli si usano soprattutto in NEGATIVE e DOMANDE (I don’t have much time; How many cats?). Nelle AFFERMATIVE è più naturale a lot of (o so much / so many)."},{"t":"wrong","s":"We had much fun  ·  She has many friends  (affermative)"},{"t":"right","s":"We had a lot of fun  ·  She has a lot of friends"}],"cat":"Nomi, articoli & quantità"},{"n":44,"title":"i pasti: have / eat / drink","items":[{"t":"exp","s":"Per i pasti si usa have (o eat): have breakfast, have lunch, have dinner. Le bevande si DRINK o si HAVE, mai eat. E “pronto per il pasto” = ready for breakfast (o ready to have breakfast)."},{"t":"wrong","s":"I ate a cup of chicory  ·  ready to breakfast"},{"t":"right","s":"I had a cup of chicory / I drank it  ·  ready for breakfast"}],"cat":"Extra & lessico"},{"n":45,"title":"keep + -ing (continuare a fare)","items":[{"t":"exp","s":"keep (o keep on) + verbo in -ing = continuare a fare qualcosa: it keeps raining, she keeps talking, keep going!"},{"t":"wrong","s":"it keeps rain  ·  keep to talk"},{"t":"right","s":"it keeps raining  ·  she keeps talking  ·  keep going"}],"cat":"Verbi & tempi"},{"n":46,"title":"ain’t (informale) — da capire, non da usare","items":[{"t":"exp","s":"ain’t è una contrazione INFORMALE/dialettale che sta per am not, is not, are not, has not, have not. Comunissima nelle canzoni e nel parlato colloquiale, ma NON si usa in inglese formale o scritto."},{"t":"exp","s":"Nelle canzoni spesso va con la doppia negazione (I ain’t got no money) — che nello standard non si fa. Tu capiscila, ma usa le forme normali."},{"t":"wrong","s":"(formale) I ain’t ready · he ain’t here · I ain’t got money"},{"t":"right","s":"I’m not ready · he isn’t here · I don’t have any money"}],"cat":"Extra & lessico"},{"n":47,"title":"get (verbo jolly) — GET · GOT · GOT/GOTTEN","items":[{"t":"exp","s":"1) **get** + sostantivo = ottenere / comprare / ricevere: When are you going to **get** your new car? I’ve just **got** an email."},{"t":"exp","s":"2) **get** + qualcuno + qualcosa = portare / prendere per qualcuno: Can you **get** me a bottle? I need to **get** my mum some butter."},{"t":"exp","s":"3) **get** + aggettivo = diventare, farsi: it’s **getting** hot; I hope you **get** better soon; I **got** very tired."},{"t":"exp","s":"4) **get** + luogo = arrivare / raggiungere: How long does it take to **get** to the station? When will you **get** there?"},{"t":"exp","s":"5) **get** = capire (= understand): I don’t **get** it; he **got** the joke but I didn’t."},{"t":"exp","s":"6) **get** + participio passato = farsi fare qualcosa (causativo): Did you **get** your hair coloured? We’re **getting** the car checked."},{"t":"exp","s":"7) Phrasal verbs: **get up** (alzarsi dal letto); **get on** (salire su treno/bus/aereo, coi gradini); **get in(to)** (salire in auto/taxi, senza gradini); **get along with** (andare d’accordo con)."},{"t":"wrong","s":"get in the bus  ·  get on the car"},{"t":"right","s":"get on the bus / train  ·  get in(to) the car"}],"cat":"Verbi & tempi"},{"n":48,"title":"used to + verbo (abitudini passate)","items":[{"t":"exp","s":"soggetto + used to + verbo base = azioni/abitudini del passato che ORA non facciamo più (“una volta…”). Negativo: didn’t use to; domanda: did you use to…?"},{"t":"wrong","s":"I used to smoked  ·  I use to live there (per il passato)"},{"t":"right","s":"I used to smoke (una volta fumavo)  ·  I used to live in Rome"}],"cat":"Verbi & tempi"},{"n":49,"title":"present perfect: been vs gone","items":[{"t":"exp","s":"has/have BEEN = andato e TORNATO (c’è stato). has/have GONE = andato e ANCORA lì (non è tornato)."},{"t":"right","s":"He has been to Paris (c’è stato, è tornato)  ·  He has gone to Paris (è ancora lì)"}],"cat":"Verbi & tempi"},{"n":50,"title":"present perfect continuous (have been + -ing)","items":[{"t":"exp","s":"have/has been + verbo-ing = azione iniziata nel passato e ANCORA in corso (o appena finita), spesso con for/since."},{"t":"wrong","s":"I am dreaming of this since years"},{"t":"right","s":"I’ve been dreaming of this for years  ·  She has been working all day"}],"cat":"Verbi & tempi"},{"n":51,"title":"l’orario (telling the time)","items":[{"t":"exp","s":"Da :01 a :30 → PAST (l’ora “e” i minuti): ten past five (5:10), quarter past (e un quarto), half past (e mezza)."},{"t":"exp","s":"Da :31 a :59 → TO (i minuti che MANCANO all’ora successiva): twenty to six (5:40), quarter to ten (9:45)."},{"t":"exp","s":"Ore esatte: seven o’clock. Lo zero dei minuti si legge “oh”: 5:05 = five oh five. La forma digitale è sempre valida: five forty."},{"t":"exp","s":"midday / noon = 12:00 (mezzogiorno); midnight = 00:00 (mezzanotte). 13:40 = 1:40 pm = twenty to two."},{"t":"wrong","s":"a quarter post seven  ·  it’s five five (5:05)"},{"t":"right","s":"a quarter past seven  ·  it’s five oh five"}],"cat":"Extra & lessico"},{"n":52,"title":"to vs for","items":[{"t":"exp","s":"**TO** — 1) distanza (luogo/tempo): a quarter **to** eleven; 6 km from my house **to** the office. 2) destinazione: I go **to** school. 3) preferenza: I prefer pizza **to** salad. 4) dare qc a qualcuno: I gave a book **to** my sister. 5) motivo, se dopo c’è un VERBO: I came here **to** see you; let’s go out **to** eat pizza."},{"t":"exp","s":"**FOR** — 1) beneficio: running is good **for** your health. 2) durata: they have lived here **for** three years. 3) favore / buona azione: I’m baking a cake **for** my sister. 4) funzione di un oggetto: the camera is used **for** recording videos. 5) programma/appuntamento: an appointment **for** May 3rd. 6) motivo, se dopo c’è un SOSTANTIVO: let’s go out **for** a pizza; Mark is studying **for** work."},{"t":"exp","s":"Trucco per il “motivo”: dopo un VERBO → **to** (to see you); dopo un SOSTANTIVO → **for** (for a pizza)."},{"t":"exp","s":"Stessa frase, senso diverso: a phone call **to** my mum (destinazione: a mia madre) vs a phone call **for** my mum (favore: per mia madre)."},{"t":"wrong","s":"I came here for see you  ·  let’s go out to a pizza"},{"t":"right","s":"I came here to see you (verbo)  ·  let’s go out for a pizza (sostantivo)"}],"cat":"Preposizioni"},{"n":53,"title":"might (possibilità)","items":[{"t":"exp","s":"**might** = “potrebbe / forse”. Struttura: might + verbo BASE (senza to): It might rain; She might be late; I might call you. Negativo: might not."},{"t":"wrong","s":"I might to call you  ·  It maybe rains"},{"t":"right","s":"I might call you  ·  It might rain"}],"cat":"Verbi & tempi"},{"n":54,"title":"so-called (per l’ironia)","items":[{"t":"exp","s":"**so-called** = “sedicente / cosiddetto”, si mette prima del nome per fare ironia o prendere le distanze: my so-called coffee = il mio “caffè” (finto)."},{"t":"exp","s":"Attenzione: “a pretend X” è infantile (a pretend kitchen = cucina giocattolo). Per l’ironia usa so-called o fake."},{"t":"wrong","s":"my pretend coffee (se vuoi l’ironia)"},{"t":"right","s":"my so-called coffee  ·  my fake coffee"}],"cat":"Extra & lessico"},{"n":55,"title":"end up + -ing (finire per fare)","items":[{"t":"exp","s":"**end up** + verbo in -ing = “finire per / ritrovarsi a fare”: I always end up giving up; we ended up staying home."},{"t":"wrong","s":"it ends to give up  ·  I end up to give up"},{"t":"right","s":"I end up giving up  ·  we ended up staying home"}],"cat":"Verbi & tempi"},{"n":56,"title":"Vocabolario — parole giuste","items":[{"t":"exp","s":"date = appuntamento romantico; appointment = parrucchiere, medico, estetista."},{"t":"exp","s":"give (non “gift” come verbo): he gives her a credit card."},{"t":"exp","s":"infantilize women (verbo attivo) oppure women are infantilized (passivo), non “are infantilize”."}],"cat":"Extra & lessico"},{"n":57,"title":"Raccontare un film o una serie: presente per la trama, passato per il ‘prima’","items":[{"t":"exp","s":"La **trama** (quello che accade nella storia) si racconta al **present simple**, anche se il film l’hai visto ieri: the story is about a woman; she dies and arrives in a good place; a man tells her she is dead."},{"t":"exp","s":"Ciò che è successo **prima** di quel punto (l’antefatto, la vita del personaggio) va al **past simple**: he tells her that she did many good things in her life."},{"t":"exp","s":"I verbi che introducono (tell, say, know, explain…) restano al **presente**; ciò che riportano sul passato va al **passato**: he says she helped people, but she never did."},{"t":"exp","s":"Persona **viva** → present perfect per l’esperienza (she has never helped anyone: la vita è ancora aperta). Persona **morta** → past simple, perché la vita è un periodo chiuso (she never helped anyone)."},{"t":"wrong","s":"a man told her she is dead  ·  (lei è morta) she has never done those things"},{"t":"right","s":"a man tells her she is dead  ·  she never did those things"}],"cat":"Verbi & tempi"}],"vocab":[{"en":"above","it":"sopra","extra":"a-BÁV"},{"en":"always","it":"sempre","extra":"ÓL-ueiz"},{"en":"ant","it":"formica","extra":""},{"en":"anywhere","it":"da qualche parte (negative e domande)","extra":""},{"en":"bad","it":"cattivo","extra":""},{"en":"bare","it":"nudo, spoglio","extra":"bèa"},{"en":"bathroom","it":"bagno","extra":""},{"en":"beautiful","it":"bello","extra":"BIÚ-ti-ful"},{"en":"bed","it":"letto","extra":""},{"en":"bedroom","it":"camera da letto","extra":""},{"en":"below","it":"sotto, più in basso","extra":"bi-LÓU"},{"en":"beneath","it":"sotto (formale, poetico)","extra":"bi-NÌITH"},{"en":"big","it":"grande","extra":""},{"en":"bread","it":"pane","extra":"bred"},{"en":"breakfast","it":"colazione","extra":"BRÉK-fast"},{"en":"brother","it":"fratello","extra":"BRÁ-da"},{"en":"busy","it":"impegnato","extra":"BÍ-zi"},{"en":"to buy","it":"comprare","extra":"BÁI"},{"en":"by","it":"vicino, accanto (by the window)","extra":"bai"},{"en":"to cast (cast–cast–cast)","it":"lanciare, gettare (to cast a spell)","extra":"caast"},{"en":"to catch (caught–caught)","it":"afferrare, prendere","extra":"chèc"},{"en":"chair","it":"sedia","extra":"cèa"},{"en":"cheek","it":"guancia","extra":"CIÌK"},{"en":"cheese","it":"formaggio","extra":"ciiz"},{"en":"child (pl. children)","it":"bambino/a","extra":""},{"en":"clover","it":"trifoglio","extra":"CLÓU-va"},{"en":"coffee","it":"caffè","extra":"CÓ-fi"},{"en":"cold","it":"freddo","extra":""},{"en":"to come","it":"venire","extra":""},{"en":"daughter","it":"figlia","extra":"DÓ-ta"},{"en":"day","it":"giorno","extra":"dei"},{"en":"to dine","it":"cenare (formale, = have dinner)","extra":"dain"},{"en":"to do","it":"fare","extra":""},{"en":"door","it":"porta","extra":"doo"},{"en":"to drink","it":"bere","extra":""},{"en":"to drop (dropped)","it":"far cadere, lasciar cadere","extra":""},{"en":"easy","it":"facile","extra":"ÌI-zi"},{"en":"to eat","it":"mangiare","extra":""},{"en":"egg","it":"uovo","extra":""},{"en":"evening","it":"sera","extra":"ÌIV-ning"},{"en":"fast","it":"veloce","extra":""},{"en":"father","it":"padre","extra":"FÁ-da"},{"en":"to feel","it":"sentire, provare","extra":""},{"en":"to find","it":"trovare","extra":""},{"en":"fish","it":"pesce","extra":""},{"en":"floor","it":"pavimento","extra":"floo"},{"en":"friend","it":"amico/a","extra":"frend"},{"en":"fruit","it":"frutta","extra":"fruut"},{"en":"gloom","it":"oscurità, tetraggine","extra":"gluum"},{"en":"to go","it":"andare","extra":""},{"en":"good","it":"buono","extra":""},{"en":"happy","it":"felice","extra":""},{"en":"hard","it":"difficile","extra":""},{"en":"to have","it":"avere","extra":""},{"en":"to hop","it":"saltellare (su un piede)","extra":""},{"en":"hot","it":"caldo","extra":""},{"en":"hour","it":"ora","extra":"áua (h muta)"},{"en":"house / home","it":"casa","extra":""},{"en":"husband","it":"marito","extra":"HÁZ-band"},{"en":"keen","it":"entusiasta, desideroso, volenteroso","extra":"kiin"},{"en":"keen on (+ -ing/nome)","it":"appassionato di","extra":""},{"en":"keen to (+ verbo)","it":"desideroso di, non vedo l’ora di","extra":""},{"en":"key","it":"chiave","extra":"kii"},{"en":"kitchen","it":"cucina","extra":"KÌ-cin"},{"en":"knee","it":"ginocchio","extra":"nii (k muta)"},{"en":"to know","it":"sapere / conoscere","extra":"NÓU (k muta)"},{"en":"to land","it":"atterrare","extra":""},{"en":"leaf (pl. leaves)","it":"foglia","extra":"liif / liivz"},{"en":"light","it":"luce","extra":"lait"},{"en":"lover","it":"amante, innamorato/a","extra":"LÁ-va"},{"en":"to make","it":"fare","extra":""},{"en":"man","it":"uomo","extra":""},{"en":"meal","it":"pasto","extra":"miil"},{"en":"meat","it":"carne","extra":"miit"},{"en":"milk","it":"latte","extra":""},{"en":"month","it":"mese","extra":"manth"},{"en":"morning","it":"mattina","extra":""},{"en":"mother","it":"madre","extra":"MÁ-da"},{"en":"neighbour","it":"vicino di casa","extra":"NÉI-ba"},{"en":"never","it":"mai","extra":"NÉ-va"},{"en":"new","it":"nuovo","extra":"niu"},{"en":"night","it":"notte","extra":"nait"},{"en":"now","it":"adesso","extra":""},{"en":"often","it":"spesso","extra":"Ó-fen (t spesso muta)"},{"en":"old","it":"vecchio","extra":"ould"},{"en":"out loud","it":"a voce alta (= aloud)","extra":"aut LÁUD"},{"en":"pathway","it":"sentiero","extra":""},{"en":"people","it":"gente / persone","extra":"PÌI-pol"},{"en":"pinky","it":"mignolo","extra":""},{"en":"pond","it":"stagno","extra":""},{"en":"room","it":"stanza","extra":""},{"en":"sad","it":"triste","extra":""},{"en":"salt","it":"sale","extra":""},{"en":"to say","it":"dire","extra":"SÉI"},{"en":"to see","it":"vedere","extra":""},{"en":"shoulder","it":"spalla","extra":"SCIÓUL-da"},{"en":"sister","it":"sorella","extra":""},{"en":"to sit (sat–sat)","it":"sedersi (sat by = seduto accanto)","extra":""},{"en":"slow","it":"lento","extra":""},{"en":"small","it":"piccolo","extra":""},{"en":"sometimes","it":"a volte","extra":""},{"en":"somewhere","it":"da qualche parte (affermative e domande “positive”)","extra":"SÁM-uea"},{"en":"son","it":"figlio","extra":"san"},{"en":"spell","it":"incantesimo (to cast a spell)","extra":""},{"en":"strength","it":"forza","extra":"strengkth"},{"en":"sugar","it":"zucchero","extra":"SCIÚ-ga"},{"en":"table","it":"tavolo","extra":""},{"en":"to take","it":"prendere","extra":""},{"en":"to tell","it":"dire, raccontare","extra":""},{"en":"then","it":"allora, poi","extra":""},{"en":"to think","it":"pensare","extra":""},{"en":"thrill","it":"brivido, emozione forte","extra":"thril"},{"en":"to throw (threw–thrown)","it":"lanciare, buttare","extra":"THRÓU (w muta)"},{"en":"thumb","it":"pollice","extra":"THAM (b muta)"},{"en":"tired","it":"stanco","extra":"TÁI-ad"},{"en":"today","it":"oggi","extra":""},{"en":"tomorrow","it":"domani","extra":""},{"en":"under","it":"sotto (generico)","extra":""},{"en":"underneath","it":"sotto (nascosto da qualcosa sopra)","extra":""},{"en":"to want","it":"volere","extra":"UÓNT"},{"en":"wall","it":"parete / muro","extra":""},{"en":"water","it":"acqua","extra":"UÓ-ta"},{"en":"week","it":"settimana","extra":"uìik"},{"en":"weekend","it":"fine settimana","extra":""},{"en":"wife","it":"moglie","extra":"UÁIF"},{"en":"window","it":"finestra","extra":""},{"en":"woman","it":"donna","extra":"UÙ-man"},{"en":"to work","it":"lavorare","extra":"UÖRK"},{"en":"year","it":"anno","extra":"iìa"},{"en":"yesterday","it":"ieri","extra":""}],"idiomi":[{"en":"to be about to","it":"stare per (fare)","extra":"I was about to leave when you called."},{"en":"How long does it take?","it":"quanto (tempo) ci vuole?","extra":"How long does it take to get there? · (passato) How long did it take? · (futuro) How long will it take?"},{"en":"by the way","it":"a proposito / tra l’altro","extra":"By the way, did you call her?"},{"en":"to change one’s mind","it":"cambiare idea","extra":"She changed her mind at the last minute."},{"en":"to feel like (+ -ing)","it":"avere voglia di","extra":"I feel like watching a film tonight."},{"en":"to have someone in the palm of your hand","it":"avere qualcuno in pugno","extra":"She has him in the palm of her hand."},{"en":"to be in a hurry","it":"avere fretta","extra":"Sorry, I’m in a hurry!"},{"en":"to know … like the back of your hand","it":"conoscere a menadito, perfettamente","extra":"I know this city like the back of my hand."},{"en":"to make up one’s mind","it":"decidersi","extra":"Hurry up and make up your mind!"},{"en":"never mind","it":"non importa / lascia perdere","extra":"Never mind, it’s not important."},{"en":"of course","it":"certo / ovviamente","extra":"Of course I’ll help you."},{"en":"once in a while","it":"ogni tanto","extra":"We go to the cinema once in a while."},{"en":"to be worth it","it":"valerne la pena","extra":"It was hard, but it was worth it."},{"en":"to grow suspicious","it":"insospettirsi, iniziare a sospettare","extra":"She grew suspicious of the man."},{"en":"to smell a rat","it":"intuire che qualcosa non va, fiutare un inganno","extra":"Something felt wrong — she smelled a rat."},{"en":"to eat, sleep and breathe (something)","it":"vivere per qualcosa, pensarci in continuazione","extra":"My daughter is into music. She eats, sleeps and breathes R'n'B."},{"en":"blood, sweat and tears","it":"sudore e sacrificio (impegno enorme)","extra":"His career isn't based on luck; he worked his way to the top with blood, sweat and tears."},{"en":"to be raring to go","it":"avere una voglia matta di iniziare","extra":"My son loves football. He's raring to watch the next game."},{"en":"to hang on by your fingernails","it":"resistere a stento, aggrapparsi con le unghie","extra":"The situation remains critical after the earthquake, as the survivors are hanging on by their fingernails, waiting to be rescued."},{"en":"to be first out of the gate","it":"essere il primo a partire/iniziare qualcosa","extra":"I was first out of the gate when I started driving to school."},{"en":"to have your heart set on (something)","it":"desiderare ardentemente qualcosa","extra":"I've had my heart set on getting into Harvard for years."},{"en":"to punch above your weight","it":"ottenere/fare più di quanto ci si aspetti dalle proprie capacità","extra":"He was punching above his weight when he volunteered for this project, since it was too complicated for him."},{"en":"to sink your teeth into (something)","it":"dedicarsi anima e corpo a qualcosa","extra":"As Jennifer started practising yoga, she sank her teeth into her practice."},{"en":"to be cut to the quick","it":"essere ferito nel profondo, offeso gravemente","extra":"Charles was cut to the quick when he was accused of stealing from his family."},{"en":"to have a bee in your bonnet (about something)","it":"avere un chiodo fisso","extra":"She has a bee in her bonnet about finding a job in the fashion industry."}],"canzoni":[{"song":"Anyone Who Knows What Love Is (Will Understand)","artist":"Irma Thomas","items":[{"en":"to care for someone","it":"tenere a qualcuno, avere a cuore","ex":"I really care for my friends."},{"en":"to blame someone (for something)","it":"dare la colpa a qualcuno","ex":"Don’t blame me for the mistake."},{"en":"to put someone down","it":"sminuire, umiliare qualcuno","ex":"He always puts her down in front of others."},{"en":"to be there for someone","it":"esserci per qualcuno, dare sostegno","ex":"Don’t worry — I’ll always be there for you."},{"en":"to feel sorry for someone","it":"dispiacersi per / compatire qualcuno","ex":"I feel sorry for him; he’s having a hard time."},{"en":"to pity someone","it":"provare pietà per qualcuno","ex":"She doesn’t want people to pity her."},{"en":"foolish","it":"sciocco, stupido, insensato","ex":"It was a foolish decision."},{"en":"to let go / letting go","it":"lasciar andare (gerundio: letting go)","ex":"Sometimes you just have to let go."},{"en":"more than I can stand (o bear)","it":"più di quanto io possa sopportare","ex":"This heat is more than I can stand."},{"en":"anyone who…","it":"chiunque…","ex":"Anyone who works hard will succeed."}]},{"song":"At Last","artist":"Etta James","items":[{"en":"to come along","it":"arrivare, presentarsi (farsi vivo)","ex":"The right person finally came along."},{"en":"to be in clover","it":"essere al settimo cielo, nell’abbondanza","ex":"Since she got the job, she’s in clover."},{"en":"to call something my own","it":"avere qualcosa di proprio","ex":"At last I have a home I can call my own."},{"en":"at last","it":"finalmente (dopo una lunga attesa)","ex":"At last, the summer is here!"},{"en":"here we are","it":"eccoci (qui)","ex":"Here we are, home at last."},{"en":"to press one’s cheek to","it":"premere la guancia contro","ex":"She pressed her cheek to his shoulder."},{"en":"a dream I’ve never known","it":"un sogno che non ho mai conosciuto (present perfect: have + participio)","ex":"This is a happiness I’ve never known."}]},{"song":"Stormy Weather","artist":"Etta James","items":[{"en":"stormy weather","it":"tempo burrascoso, brutto tempo (anche in senso figurato)","ex":"There’s stormy weather coming this weekend."},{"en":"to keep raining (keep + -ing)","it":"continuare a piovere / continuare a fare","ex":"It kept raining all day."},{"en":"to pull / get oneself together","it":"riprendersi, ricomporsi","ex":"Come on, pull yourself together!"},{"en":"can’t go on","it":"non andare avanti, non farcela più","ex":"I can’t go on like this."},{"en":"all the time","it":"di continuo, tutto il tempo","ex":"He talks about work all the time."}]}],"racconti":[{"title":"Racconto 1 — Il metodo del mio insegnante e Adept English  (30/07/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"My English teacher says that if you want to speak English well, the right way is to listen to everything — podcasts, movies — every day, just for a short time, but every single day. It's how a baby learns to speak from their parents. Actually, my “English teacher” is really just an English podcast I listen to sometimes."},{"t":"plain","s":"The podcast I listen to is called Adept English. Hilary, the teacher, starts each episode by explaining her method and the topic. She says that if you listen to her podcast and don't understand it, then it isn't right for you, because it's meant for intermediate level. I understand a lot of what she says, but then I don't remember it and I'm not able to repeat what she said."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"My English **teacher** says / that if you want to **speak** English **well**, / the **right way** / is to listen to **everything** — / **podcasts**, / **movies** — / **every day**, / just for a **short time**, / but **every single day**. //"},{"t":"marked","s":"It's **how** a **baby** learns to **speak** / from their **parents**. // **Actually**, / my “English **teacher**” / is really just an English **podcast** / I listen to **sometimes**. //"},{"t":"marked","s":"The **podcast** I listen to / is called **Adept English**. // **Hilary**, / the **teacher**, / starts each **episode** / by explaining her **method** / and the **topic**. //"},{"t":"marked","s":"She says / that if you **listen** to her podcast / and **don't understand** it, / then it **isn't right** for you, / because it's meant for **intermediate** level. //"},{"t":"marked","s":"I understand a **lot** of what she says, / but then I don't **remember** it, / and I'm not able to **repeat** / what she **said**. //"},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"},{"t":"label","s":"Un mese dopo — versione aggiornata e ampliata (25/08/2026)"},{"t":"plain","s":"Today I had an idea: to improve my English, I have to review the rules. I'll write some stories to reinforce the rules; then I'll read them out loud to practice my pronunciation. I started from my first stories, where I explained what my English teacher says about the method for learning it. I decided to read and rewrite them to expand the topic."},{"t":"plain","s":"My teacher, called Hillary, says that if you want to speak English fluently, the right method for doing it is to listen to podcasts, movies, series and cartoons every day — everything in English, for a few minutes, but every day."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"**Today** I had an **idea**: / to **improve** my English, / I have to **review** the **rules**. // I'll **write** some **stories** / to **reinforce** the **rules**; / then I'll **read** them **out loud** / to **practice** my **pronunciation**. //"},{"t":"marked","s":"I **started** from my **first stories**, / where I **explained** / what my English **teacher** says / about the **method** for **learning** it. // I **decided** to **read** and **rewrite** them / to **expand** the **topic**. //"},{"t":"marked","s":"My **teacher**, / called **Hillary**, / says that if you want to **speak** English **fluently**, / the **right method** for **doing** it / is to **listen** to **podcasts**, / **movies**, / **series** / and **cartoons** / **every day** — //"},{"t":"marked","s":"**everything** in **English**, / for a **few minutes**, / but **every day**. //"},{"t":"note","s":"Dopo method si usa for + -ing (the method for learning), non method + to + verbo."},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"},{"t":"plain","s":"This method is inspired by babies who learn to speak because they listen to someone — like their parents — talk every day. It starts with a few words — mom, dad — to get to more difficult words and whole sentences."},{"t":"plain","s":"Sometimes I think about giving up studying English; I'm so frustrated by this situation. I study a lot, but I'm not able to speak and write correctly yet. I've been studying for several hours, only to forget everything later and make the same mistakes again. When someone asks me something, I don't understand immediately."},{"t":"plain","s":"Now it would be better to stop. Today I've been studying and writing enough; I made many mistakes again. I have to relax and maybe tomorrow it will be better. I'll watch a movie."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"This **method** is **inspired** by **babies** / who **learn** to **speak** / because they **listen** to **someone** — / like their **parents** — / **talk** **every day**. //"},{"t":"marked","s":"It **starts** with a **few words** — / **mom**, / **dad** — / to **get** to more **difficult words** / and **whole sentences**. //"},{"t":"marked","s":"**Sometimes** I think about **giving up** / studying **English**; / I'm so **frustrated** / by this **situation**. // I **study** a **lot**, / but I'm not **able** to **speak** / and **write correctly** yet. //"},{"t":"marked","s":"I've been **studying** / for **several hours**, / **only** to **forget everything** later / and make the **same mistakes** again. // When **someone** asks me **something**, / I don't **understand** **immediately**. //"},{"t":"marked","s":"**Now** it would be **better** to **stop**. // **Today** I've been **studying** and **writing** enough; / I made **many mistakes** again. // I have to **relax** / and **maybe tomorrow** / it will be **better**. // I'll **watch** a **movie**. //"},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 2 — L’episodio “The perfect boyfriend”  (30/07/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"In this podcast, Hilary talks about a trend on social media — like Instagram, TikTok, or Facebook — that shows a perfect boyfriend who pays for everything his girlfriend wants. But that's not enough: the perfect boyfriend also organizes and books every appointment for his girlfriend — hairdresser, beautician, restaurant. On top of that, he gives her a credit card for her shopping. Hilary and her fellow therapists hate this trend. They say these relationships infantilize women, and that this isn't the right path toward women's emancipation."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"In this **podcast**, / Hilary talks about a **trend** on social media — / like **Instagram**, / **TikTok**, / or **Facebook** — / that shows a **perfect boyfriend** / who **pays** for everything / his **girlfriend** wants. //"},{"t":"marked","s":"But that's **not enough**: / the perfect boyfriend **also** / organizes and **books** / every **appointment** for his girlfriend — / **hairdresser**, / **beautician**, / **restaurant**. // On **top** of that, / he **gives** her a **credit card** / for her **shopping**. //"},{"t":"marked","s":"Hilary and her **fellow therapists** / **hate** this trend. // They say / these **relationships** / **infantilize** women, / and that this **isn't** the right **path** / toward women's **emancipation**. //"},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 3 — La mia amica Elena  (30/07/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"Let me tell you about my dear friend Elena. She's Greek but has lived in Italy with her family for several years. Now they live in the countryside, far from where I live, so we meet rarely, but we often talk on the phone. She's married to Frank, and I was at their wedding. They have two children, a daughter and a son; they are polite children who love their parents dearly. Elena works in a food factory; her job is quality assurance, like mine, while her husband is retired. We studied and graduated from the same university a few years ago. After graduation, she went to Greece for a few months to look for a job, then she returned to Italy. Elena and her son both love playing the piano, but Elena is the only one who also loves walking in the woods, riding her motorbike, and animals — she has three cats and two dogs. On the other hand, Elena and her daughter both love watching movies and running. In the past, the two of us sometimes went to Greece on holiday; a long time has passed, but in September we'll go back to Greece for a short holiday."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"Let me tell you about my dear **friend** **Elena**. // She's **Greek** / but has lived in **Italy** / with her family / for **several years**. // **Now** they live in the **countryside**, / far from where I **live**, / so we meet **rarely**, / but we often talk on the **phone**. //"},{"t":"marked","s":"She's married to **Frank**, / and I was at their **wedding**. // They have **two** children, / a daughter and a **son**; // they're **polite** children / who love their parents **dearly**. //"},{"t":"marked","s":"**Elena** works in a **food factory**; / her job is **quality assurance**, / like **mine**, / while her husband is **retired**. // We studied and **graduated** / from the same **university** / a few years **ago**. //"},{"t":"marked","s":"After **graduation**, / she went to **Greece** / for a few **months** / to look for a **job**, / then she returned to **Italy**. //"},{"t":"marked","s":"**Elena** and her **son** / **both** love playing the **piano**, / but **Elena** / is the **only** one / who also loves / walking in the **woods**, / riding her **motorbike**, / and **animals** — / she has **three** cats / and **two** dogs. //"},{"t":"marked","s":"On the **other hand**, / **Elena** and her **daughter** / both love / watching **movies** / and **running**. // In the **past**, / the two of us / sometimes went to **Greece** / on **holiday**; // a long time has **passed**, / but in **September** / we'll go **back** to **Greece** / for a short **holiday**. //"},{"t":"note","s":"Nota il contrasto: in “both love the piano, but Elena is the only one…” l’accento cade su BOTH e su ONLY, perché sono il cuore del confronto. È lì che sta il significato."},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 4 — L’episodio sul “junk food”  (30/07/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"Today's podcast topic is junk food. “Junk” means things that have little value; for example, we use it with words like “email” and “food.” Hilary tells us about the government's list of junk foods that must not be advertised before 9 p.m. When we think about junk food, we might think of the food we eat at McDonald's or Burger King — what some people call “fast food” — but the government's list also includes typical British dishes and breakfast foods like fruit juice, porridge, cereal, yoghurt, and doughnuts. They're responsible for childhood obesity because they are foods with little nutritional value and a high sugar content."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"**Today's** podcast **topic** / is **junk food**. // “**Junk**” means **things** / that have **little value**; / for **example**, / we use it with words like / “**email**” / and “**food**.” //"},{"t":"marked","s":"Hilary **tells** us / about the **government's list** / of **junk foods** / that must **not** be **advertised** / before **9 p.m.** //"},{"t":"marked","s":"When we think about **junk food**, / we might think of the food / we eat at **McDonald's** / or **Burger King** — / what some people call / “**fast food**” — / but the government's list / **also** includes / typical **British dishes** / and **breakfast foods** / like **fruit juice**, / **porridge**, / **cereal**, / **yoghurt**, / and **doughnuts**. //"},{"t":"marked","s":"They're **responsible** / for **childhood obesity**, / because they are foods / with **little nutritional value** / and a **high sugar content**. //"},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 5 — La mia famiglia  (04/08/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"I have two sisters and one brother. I'm the second child, so I have an older sister and a younger sister. My brother is the last one; he's the youngest. My husband is taller than me, so I'm shorter than him, but I'm taller than my older sister, and I'm also taller than my younger sister. My nephew Mark is the tallest in the whole family, but he's not the youngest. My niece Emma is the shortest and the youngest in the whole family."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"I have **two sisters** / and **one brother**. // I'm the **second** child, / so I have an **older** sister / and a **younger** sister. //"},{"t":"marked","s":"My **brother** is the **last** one; / he's the **youngest**. //"},{"t":"marked","s":"My **husband** is **taller** than me, / so I'm **shorter** than him, / but I'm **taller** than my **older** sister, / and I'm **also** taller than my **younger** sister. //"},{"t":"marked","s":"My nephew **Mark** / is the **tallest** in the **whole family**, / but he's **not** the **youngest**. // My niece **Emma** / is the **shortest** / and the **youngest** / in the **whole family**. //"},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 6 — La vacanza in Sardegna  (05/08/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"Last month I went on holiday with my husband's family. We went to Sardinia, an Italian island in the Mediterranean Sea. We had a wonderful time. We were on vacation for two weeks. There were nine of us: the grandparents, their three children, me, my brother-in-law, and two nephews. It was a lot of fun. It was always sunny, so I went to the beach every day. On holiday I did many things: I read, swam, ran, cooked, and I also slept a lot. Early in the morning, at 5 o'clock, I went to the beach to swim and watch the sunrise. Then I came home with breakfast for the whole family; I bought lots of croissants, doughnuts, and muffins. They were happy when they woke up. Sometimes I washed the dishes and cooked, but I never washed the windows or mopped the floor."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"**Last month** / I went on **holiday** / with my **husband's** family. // We went to **Sardinia**, / an Italian **island** / in the **Mediterranean Sea**. //"},{"t":"marked","s":"We had a **wonderful** time. // We were on **vacation** / for **two weeks**. // There were **nine** of us: / the **grandparents**, / their **three** children, / **me**, / my **brother-in-law**, / and two **nephews**. //"},{"t":"marked","s":"It was a lot of **fun**. // It was always **sunny**, / so I went to the **beach** / **every day**. //"},{"t":"marked","s":"On holiday I did **many things**: / I **read**, / **swam**, / **ran**, / **cooked**, / and I **also** slept a lot. //"},{"t":"marked","s":"Early in the **morning**, / at **five** o'clock, / I went to the **beach** / to **swim** / and watch the **sunrise**. //"},{"t":"marked","s":"Then I came **home** / with **breakfast** / for the **whole family**; // I bought lots of **croissants**, / **doughnuts**, / and **muffins**. //"},{"t":"marked","s":"They were **happy** / when they **woke up**. // Sometimes I **washed** the dishes / and **cooked**, / but I **never** washed the **windows** / or **mopped** the **floor**. //"},{"t":"label","s":"Pronunce ostiche (lettura semplificata; maiuscolo = accento)"},{"t":"pron","items":[{"w":"island","h":"ÁI-land — la “s” è MUTA"},{"w":"Mediterranean","h":"me-di-te-RÉI-ni-an"},{"w":"wonderful","h":"UÁN-der-ful"},{"w":"vacation","h":"ve-KÉI-shen"},{"w":"nephews","h":"NÉF-iuz — “ph” = f"},{"w":"brother-in-law","h":"BRÁ-ther-in-LÓ — “th” sonora (come the); law = “lo”"},{"w":"doughnuts","h":"DÓU-nats — “ough” = “ou”"},{"w":"croissants","h":"krua-SÓN — parola francese, la “t” quasi non si sente"},{"w":"woke","h":"UÓUK"},{"w":"sunrise","h":"SÁN-raiz"}]},{"t":"note","s":"Le “-ed” di washed e mopped si pronunciano come una “t”: UÓSHT, MÓPT (dopo un suono sordo, -ed = t)."},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 7 — I gatti delle mie sorelle  (06/08/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"I told you that I have two sisters; each of them has one cat. My oldest sister has a male cat, a Scottish Fold, 3 years old. It's a beautiful cat — sleepy and funny; it suddenly runs and jumps at a noise, plays with water, and wants lots of cuddles. My youngest sister also has a cat, but hers is a stray; it's black and in bad shape because it lived on the street. She will take it to the vet. These cats live differently: the first one lives in an apartment, with three or four bowls to eat from, a little house where it sleeps, a scratching post, and lots of toys like little mice or fake birds. The second one, on the other hand, lives on the street; it eats what it finds, plays outside, and fights with other cats. The first cat is called Pinco, and it's fatter than the second one, which is called Black."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"I **told** you / that I have **two sisters**; / **each** of them / has **one cat**. // My **oldest** sister / has a **male** cat, / a **Scottish Fold**, / **three years old**. //"},{"t":"marked","s":"It's a **beautiful** cat — / **sleepy** / and **funny**; / it suddenly **runs** / and **jumps** at a **noise**, / **plays** with **water**, / and **wants** lots of **cuddles**. //"},{"t":"marked","s":"My **youngest** sister / **also** has a cat, / but **hers** is a **stray**; / it's **black** / and in **bad shape** / because it **lived** on the **street**. // She will take it / to the **vet**. //"},{"t":"marked","s":"These cats live **differently**: / the **first** one / lives in an **apartment**, / with **bowls** to eat from, / a little **house** where it **sleeps**, / a **scratching post**, / and lots of **toys** / like little **mice** / or fake **birds**. //"},{"t":"marked","s":"The **second** one, / on the **other hand**, / lives on the **street**; / it **eats** what it **finds**, / **plays** outside, / and **fights** with other **cats**. //"},{"t":"marked","s":"The first cat is **called Pinco**, / and it's **fatter** / than the **second** one, / which is **called Black**. //"},{"t":"label","s":"Pronunce ostiche (lettura semplificata; maiuscolo = accento)"},{"t":"pron","items":[{"w":"Scottish Fold","h":"SKÓ-tish FÓULD — “ou” come in go"},{"w":"beautiful","h":"BIÚ-ti-ful"},{"w":"youngest","h":"IÁN-ghest — qui “ou” suona “a”"},{"w":"cuddles","h":"CÁD-els"},{"w":"apartment","h":"a-PÁRT-ment"},{"w":"scratching","h":"SKRÁ-cing — “tch” = “c” di ciao"},{"w":"mice","h":"MÁIS — plurale di mouse"},{"w":"differently","h":"DÍ-fre-ntli"},{"w":"fatter","h":"FÁ-ter — “a” corta, “tt” raddoppiata"}]},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 8 — Cosa ho mangiato ieri  (06/08/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"When I wake up, I drink a glass of water, then I wash my face and I'm ready for breakfast. Yesterday at breakfast I had a cup of instant chicory — I don't drink coffee because I think it makes me nervous; it's a good alternative. I didn't just drink; I also ate a slice of plumcake and some biscuits. I'm bad at cooking, but I make an excellent plumcake. At lunch I cooked a typical Indonesian dish called Nasi Goreng, a rice-based dish with some vegetables, a few pieces of chicken, and a fried egg on top. Then I ate some fruit; there was a lot of fruit in my fridge, but I preferred to eat a few apricots — I don't remember how many there were — some peaches, and a slice of watermelon. In the afternoon I drank a cup of instant chicory with some biscuits. At dinner I ate a salad, some bread with a slice of salmon, and a lot of fried peppers, which I love."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"When I **wake up**, / I drink a **glass of water**, / then I **wash** my face / and I'm **ready** for **breakfast**. //"},{"t":"marked","s":"Yesterday at **breakfast** / I **had** a cup of instant **chicory** — / I don't drink **coffee** / because I think it makes me **nervous**; / it's a **good alternative**. //"},{"t":"marked","s":"I didn't **just drink**; / I **also** ate a slice of **plumcake** / and some **biscuits**. // I'm **bad at cooking**, / but I make an **excellent plumcake**. //"},{"t":"marked","s":"At **lunch** / I cooked a typical **Indonesian** dish / called **Nasi Goreng**, / a **rice-based** dish / with some **vegetables**, / a few pieces of **chicken**, / and a **fried egg** on top. //"},{"t":"marked","s":"Then I ate some **fruit**; / there was **a lot of** fruit in my fridge, / but I **preferred** to eat / a few **apricots** — / some **peaches**, / and a slice of **watermelon**. //"},{"t":"marked","s":"In the **afternoon** / I **drank** a cup of instant **chicory** / with some **biscuits**. // At **dinner** / I ate a **salad**, / some **bread** with a slice of **salmon**, / and **a lot of** fried **peppers**, / which I **love**. //"},{"t":"label","s":"Pronunce ostiche (lettura semplificata; maiuscolo = accento)"},{"t":"pron","items":[{"w":"chicory","h":"CÌ-ko-ri — “ch” = c di ciao"},{"w":"plumcake","h":"PLÁM-keik — “u” suona “a”"},{"w":"vegetables","h":"VÉG-te-bols — 3 sillabe, la 2ª quasi sparisce"},{"w":"chicken","h":"CÌ-ken — “ch” = c di ciao"},{"w":"apricots","h":"ÉI-pri-kots"},{"w":"peaches","h":"PÌI-cis — “ea” = ii lunga"},{"w":"watermelon","h":"UÓ-ter-me-lon"},{"w":"salmon","h":"SÁ-men — la “l” è MUTA!"},{"w":"excellent","h":"ÉK-se-lent"}]},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 9 — La mia giornata (My morning)  (12/08/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"I usually get up at 7 am; when I wake up, the first thing I do is look at the clock. I'm not sleeping well these days — it's hotter than last year in August, and the nights are hot too, so I wake up tired every morning. So I go to the bathroom and wash my face to wake myself up. Then I go to the kitchen to make breakfast, but first I drink a glass of water. I put two spoonfuls of instant chicory and some water in a cup: my coffee substitute is ready. I don't drink coffee anymore because I think it makes me nervous. By the way, the last time I drank coffee was on holiday in February. I used to drink a lot of coffee, many times a day, but maybe it was too much for me. I looked for a healthy alternative: I tasted a cup of instant chicory at my sister's house, I liked it, and I'm keen on drinking it. I don't just drink; I also eat a slice of plumcake and some biscuits. I'm bad at cooking, but I make an excellent plumcake and a few other things. I read the newspaper while I'm having breakfast, then I check my email and reply if necessary. After reading the newspaper, I start to study English — this is my goal this month. I think my English level is very low, so I need to study every day for a long time. This has been my goal for several years, but I always reach the same point and end up giving up. This time I have faith in this project, because I've found the right help and the correct method. At 10 o'clock I go to the gym with my friends for about two hours; I train, and when I'm tired I take a shower and go home. When I get home, it's lunchtime: I open the fridge and decide what to cook. For lunch I usually have some rice with vegetables, an omelette, pasta, or a tasty one-dish meal with some meat and vegetables. I love eating fruit; my favourite is apricots, but I also like peaches, avocados, and yellow melons. On the other hand, I don't like apples, cherries, or mangoes. In the afternoon I start studying again while I drink a cup of chicory. I might also get a phone call from my sister."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"I usually **get up** at **7 am**; / when I **wake up**, / the first thing I do / is look at the **clock**. // I'm **not sleeping well** these days — / it's **hotter** than last year in **August**, / and the **nights** are hot too, / so I **wake up tired** / **every morning**. //"},{"t":"marked","s":"So I go to the **bathroom** / and **wash** my face / to **wake myself up**. // Then I go to the **kitchen** / to make **breakfast**, / but **first** I drink a **glass of water**. //"},{"t":"marked","s":"I put **two spoonfuls** of instant **chicory** / and some **water** in a **cup**: / my **coffee substitute** is **ready**. // I don't drink coffee **anymore** / because I think it makes me **nervous**. //"},{"t":"marked","s":"By the way, / the **last time** I drank coffee / was on **holiday** in **February**. // I **used to** drink a lot of **coffee**, / many times a **day**, / but maybe it was **too much** for me. //"},{"t":"marked","s":"I **looked for** a healthy **alternative**: / I **tasted** a cup of instant **chicory** / at my **sister's house**, / I **liked** it, / and I'm **keen on drinking** it. //"},{"t":"marked","s":"I don't **just drink**; / I **also eat** a slice of **plumcake** / and some **biscuits**. // I'm **bad at cooking**, / but I make an **excellent plumcake** / and a **few other things**. //"},{"t":"marked","s":"I read the **newspaper** / while I'm having **breakfast**, / then I **check** my **email** / and **reply** if **necessary**. //"},{"t":"marked","s":"After reading the newspaper, / I start to **study English** — / this is my **goal** this **month**. // I think my English level is very **low**, / so I need to **study every day** / for a **long time**. //"},{"t":"marked","s":"This has been my **goal** / for **several years**, / but I always **reach the same point** / and **end up giving up**. // **This time** / I have **faith** in this project, / because I've **found** the **right help** / and the **correct method**. //"},{"t":"marked","s":"At **10 o'clock** / I go to the **gym** with my **friends** / for about **two hours**; / I **train**, / and when I'm **tired** / I take a **shower** / and go **home**. //"},{"t":"marked","s":"When I get **home**, / it's **lunchtime**: / I open the **fridge** / and decide **what to cook**. // For **lunch** I usually have some **rice** with **vegetables**, / an **omelette**, / **pasta**, / or a tasty **one-dish meal** / with some **meat** and **vegetables**. //"},{"t":"marked","s":"I love eating **fruit**; / my favourite is **apricots**, / but I also like **peaches**, / **avocados**, / and **yellow melons**. // On the **other hand**, / I don't like **apples**, / **cherries**, / or **mangoes**. //"},{"t":"marked","s":"In the **afternoon** / I start **studying again** / while I drink a cup of **chicory**. // I might also get a **phone call** / from my **sister**. //"},{"t":"label","s":"Pronunce ostiche (lettura semplificata; maiuscolo = accento)"},{"t":"pron","items":[{"w":"bathroom","h":"BÁTH-rum"},{"w":"vegetables","h":"VÉG-te-bols — la 2ª sillaba quasi sparisce"},{"w":"newspaper","h":"NIÙZ-pei-pa"},{"w":"biscuits","h":"BÍ-skits — “cuit” = “kit”"},{"w":"necessary","h":"NÉ-se-se-ri"},{"w":"substitute","h":"SÁB-sti-tiut"},{"w":"favourite","h":"FÉI-vrit — 2 sillabe"},{"w":"omelette","h":"ÓM-let"},{"w":"apricots","h":"ÉI-pri-kots"},{"w":"avocados","h":"a-vo-CÁ-dos"},{"w":"February","h":"FÉB-ru-eri"}]},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 10 — The Good Place, episodio 1 e 2  (23/08/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"Yesterday afternoon I watched a TV series on Netflix. I was looking for an English series to improve my English, and I found one called The Good Place, with Kristen Bell and Ted Danson."},{"t":"plain","s":"The series tells the story of Eleanor (Kristen Bell). She wakes up in an unknown place where she meets Michael (Ted Danson), who tells her that she is dead and is now in the Good Place, like heaven, because she was a good person. Michael is the architect who built this otherworldly city. He shows her the Good Place and her new home, and he says she helped a lot of people during her life. But she doesn't recognise anything: she never helped anyone in her life; she wasn't a death-row lawyer and she wasn't a good person."},{"t":"plain","s":"At her new house she meets Chidi, her soulmate and companion. She begins to suspect that something is wrong, and she confesses to her soulmate that she has arrived in the wrong place. During a walk, Eleanor and Chidi meet Michael, who is with her new neighbours, Tahani and Jason. Tahani picks on Eleanor because she is shorter and has a smaller house than hers; at one point Tahani even “boops” Eleanor on the nose. Michael says that there will be a party to which everyone is invited. At the party Eleanor drinks a lot and doesn't have fun; she says nasty things about her neighbour because she is jealous of Tahani, who picks on her and has a bigger house than hers."},{"t":"plain","s":"When Eleanor wakes up the next day, she finds a disastrous situation. Giant animals are walking through the city, there is thunder and lightning, and everyone is wearing the same yellow-and-blue dress except her. Everything she said at the party comes true. She realises she's in trouble and that she is the cause of the disaster. This is the summary of the first episode of the first season."},{"t":"plain","s":"The second episode begins with Eleanor, who realises she is the only one who isn't wearing the yellow-and-blue dress. So she calls the Good Place's virtual assistant (Janet) to get one. The whole neighbourhood meets to talk about the unpleasant event, and it seems that everything is slowly returning to normal."},{"t":"plain","s":"Michael announces that, that day, the neighbourhood will do a special activity: everyone can fly. Instead, Tahani suggests cleaning the city, and she looks for twelve volunteers to do it. She thinks that this initiative could unite the neighbourhood during a difficult moment."},{"t":"plain","s":"Eleanor makes fun of her and says she won't give up flying to clean the city. At that point, Chidi decides to step forward with Eleanor, but she isn't very happy about it. With only five minutes left before flying ends, Eleanor decides to give up cleaning, and she hides the garbage instead of picking it up."},{"t":"plain","s":"Eleanor's bad deed doesn't go unnoticed, and while she is getting ready to fly, it starts raining garbage. Chidi feels let down by Eleanor, and he won't help her become a better person. At home, Eleanor receives a message: someone knows her secret."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"**Yesterday afternoon** I watched a **TV series** on **Netflix**. // I was **looking** for an **English series** / to **improve** my **English**, / and I **found** one **called** **The Good Place**, / with **Kristen Bell** / and **Ted Danson**. //"},{"t":"marked","s":"The **series** tells the **story** of **Eleanor** / (**Kristen Bell**). // She **wakes up** / in an **unknown place** / where she **meets** **Michael** / (**Ted Danson**), / who **tells** her / that she **is dead** / and **is now** in the **Good Place**, / like **heaven**, / because she **was** a **good person**. //"},{"t":"marked","s":"**Michael** is the **architect** / who **built** this **otherworldly city**. // He **shows** her the **Good Place** / and her **new home**, / and he **says** she **helped** a **lot** of **people** / during her **life**. //"},{"t":"marked","s":"But she **doesn't recognise** anything: / she **never helped** anyone / in her **life**; / she **wasn't** a **death-row lawyer** / and she **wasn't** a **good person**. //"},{"t":"marked","s":"At her **new house** / she **meets** **Chidi**, / her **soulmate** and **companion**. // She **begins** to **suspect** / that **something** is **wrong**, / and she **confesses** to her **soulmate** / that she has **arrived** / in the **wrong place**. //"},{"t":"marked","s":"During a **walk**, / **Eleanor** and **Chidi** **meet** **Michael**, / who **is** with her **new neighbours**, / **Tahani** and **Jason**. //"},{"t":"marked","s":"**Tahani** **picks on** **Eleanor** / because she **is shorter** / and has a **smaller house** than **hers**; / at **one point** / **Tahani** even “**boops**” **Eleanor** on the **nose**. //"},{"t":"marked","s":"**Michael** **says** / that there **will be** a **party** / to **which** **everyone** is **invited**. // At the **party** **Eleanor** **drinks** a **lot** / and **doesn't have fun**; / she **says** **nasty things** about her **neighbour** / because she **is jealous** of **Tahani**, / who **picks on** her / and has a **bigger house** than **hers**. //"},{"t":"marked","s":"When **Eleanor** **wakes up** the **next day**, / she **finds** a **disastrous situation**. // **Giant animals** are **walking** through the **city**, / there **is thunder** and **lightning**, / and **everyone** is **wearing** the **same yellow-and-blue dress** / **except** her. //"},{"t":"marked","s":"**Everything** she **said** at the **party** **comes true**. // She **realises** she's in **trouble** / and that she **is** the **cause** of the **disaster**. // **This** is the **summary** / of the **first episode** / of the **first season**. //"},{"t":"marked","s":"The **second episode** **begins** with **Eleanor**, / who **realises** she **is** the **only one** / who **isn't wearing** the **yellow-and-blue dress**. // So she **calls** the **Good Place's** **virtual assistant** / (**Janet**) / to **get** one. //"},{"t":"marked","s":"The **whole neighbourhood** **meets** / to **talk about** the **unpleasant event**, / and it **seems** / that **everything** is **slowly returning** to **normal**. //"},{"t":"marked","s":"**Michael** **announces** / that, that **day**, / the **neighbourhood** will **do** a **special activity**: / **everyone** can **fly**. // **Instead**, / **Tahani** **suggests** **cleaning** the **city**, / and she **looks for** **twelve volunteers** / to **do** it. //"},{"t":"marked","s":"She **thinks** / that this **initiative** could **unite** the **neighbourhood** / during a **difficult moment**. //"},{"t":"marked","s":"**Eleanor** **makes fun of** her / and **says** she **won't give up** **flying** / to **clean** the **city**. // At that **point**, / **Chidi** **decides** to **step forward** with **Eleanor**, / but she **isn't very happy** about it. //"},{"t":"marked","s":"With only **five minutes** left / before **flying ends**, / **Eleanor** **decides** to **give up cleaning**, / and she **hides** the **garbage** / **instead of picking it up**. //"},{"t":"marked","s":"**Eleanor's bad deed** **doesn't go unnoticed**, / and while she **is getting ready** to **fly**, / it **starts raining garbage**. //"},{"t":"marked","s":"**Chidi** **feels let down** by **Eleanor**, / and he **won't help** her **become** a **better person**. // At **home**, / **Eleanor** **receives** a **message**: / **someone** **knows** her **secret**. //"},{"t":"label","s":"Pronunce ostiche (lettura semplificata; maiuscolo = accento)"},{"t":"pron","items":[{"w":"Eleanor","h":"ÉL-i-nor"},{"w":"Chidi","h":"CHÍI-di"},{"w":"Tahani","h":"ta-HÁ-ni"},{"w":"otherworldly","h":"A-ther-UÖRLD-li"},{"w":"architect","h":"ÁR-ki-tekt"},{"w":"soulmate","h":"SÓUL-meit"},{"w":"neighbourhood","h":"NÉI-ba-hud"},{"w":"unnoticed","h":"a-NÓU-tist"},{"w":"volunteers","h":"vo-lan-TÍRZ"},{"w":"initiative","h":"i-NÍ-sha-tiv"}]},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]},{"title":"Racconto 11 — Toma e il drago  (29/08/2026)","blocks":[{"t":"label","s":"Testo corretto"},{"t":"plain","s":"Yesterday I watched a short animated story on YouTube, about a small, thin man named Toma, and a hungry dragon. Toma lives in a quiet mountain village. He is a baker, and every morning he bakes warm bread and sweet rolls for the villagers. One day, panic spreads through the town: a dragon arrives."},{"t":"plain","s":"Every night, the dragon steals animals and burns crops. The villagers are afraid of him because he says that if they don't feed him, he will eat the people next. The villagers give the dragon all they can, but it is never enough."},{"t":"plain","s":"At that point, Toma makes a plan. The next morning Toma packs a basket with bread, cheese and a jug of milk, then he sets off toward the dragon's cave. When Toma arrives, the dragon blinks in surprise: it has never seen a man walk toward it without fear."},{"t":"plain","s":"Toma gives his basket to the dragon, and tells him that there is a place where it can find an endless supply of food. The dragon asks to see it, and Toma leads him there. They come to a wide grassy meadow. In the center of it there is a deep pit covered by vines and moss. While the dragon leaps in, the earth crumbles and the sides collapse. The dragon is stuck. Toma returns home, and the villagers are very happy not to see the dragon anymore."},{"t":"label","s":"Con accenti e pause (leggi ad alta voce seguendo i simboli)"},{"t":"marked","s":"**Yesterday** I **watched** a **short animated story** on **YouTube**, / about a **small**, / **thin man** / named **Toma**, / and a **hungry dragon**. //"},{"t":"marked","s":"**Toma lives** in a **quiet mountain village**. // He's a **baker**, / and **every morning** / he **bakes warm bread** / and **sweet rolls** / for the **villagers**. //"},{"t":"marked","s":"**One day**, / **panic spreads** through the **town**: / a **dragon arrives**. //"},{"t":"marked","s":"**Every night**, / the **dragon steals animals** / and **burns crops**. // The **villagers** are **afraid** of him / because he **says** / that if they **don't feed** him, / he will **eat** the **people** next. //"},{"t":"marked","s":"The **villagers give** the **dragon** / all they **can**, / but it's **never enough**. //"},{"t":"marked","s":"**At that point**, / **Toma makes** a **plan**. // The **next morning** / **Toma packs** a **basket** / with **bread**, / **cheese** / and a **jug** of **milk**, / then he **sets off** / toward the **dragon's cave**. //"},{"t":"marked","s":"When **Toma arrives**, / the **dragon blinks** in **surprise**: / it has **never seen** a **man** / **walk** toward it / **without fear**. //"},{"t":"marked","s":"**Toma gives** his **basket** to the **dragon**, / and **tells** him / that there's a **place** / where it can **find** / an **endless supply** of **food**. //"},{"t":"marked","s":"The **dragon asks** to **see** it, / and **Toma leads** him **there**. // They **come** to a **wide grassy meadow**. // In the **center** of it / there's a **deep pit** / covered by **vines** and **moss**. //"},{"t":"marked","s":"While the **dragon leaps** in, / the **earth crumbles** / and the **sides collapse**. // The **dragon** is **stuck**. // **Toma returns home**, / and the **villagers** are **very happy** / **not to see** the **dragon** **anymore**. //"},{"t":"label","s":"Pronuncia delle parole più ostiche"},{"t":"pron","items":[{"w":"dragon","h":"DRAG-uhn"},{"w":"meadow","h":"MED-oh"},{"w":"villagers","h":"VIL-lij-erz"},{"w":"collapse","h":"kuh-LAPS"},{"w":"crumbles","h":"KRUM-b'lz"},{"w":"surprise","h":"ser-PRYZE"},{"w":"supply","h":"suh-PLY"},{"w":"endless","h":"END-lis"}]},{"t":"label","s":"Le tue correzioni (barrato = errore · verde = corretto)"}]}],"phrasal":[{"pv":"to work out","it":"allenarsi","eq":"to exercise","sep":"non separabile","ex":"She has been working out at the gym lately."},{"pv":"to take up","it":"iniziare (un'attività/hobby)","eq":"to start doing","sep":"separabile","ex":"He took up woodworking after inheriting his grandfather's tools."},{"pv":"to be into","it":"essere appassionato di","eq":"to be interested in","sep":"non separabile","ex":"When I was young I was into volleyball."},{"pv":"to give up","it":"smettere, rinunciare, arrendersi","eq":"to stop, to quit","sep":"separabile","ex":"I gave up smoking. / I gave it up."},{"pv":"to carry on","it":"continuare (a fare)","eq":"to continue","sep":"non separabile","ex":"Carry on with your work."},{"pv":"to get on with","it":"procedere / andare avanti con","eq":"to progress with","sep":"non separabile","ex":"How are you getting on with the project?"},{"pv":"to get rid of","it":"liberarsi di, eliminare","eq":"to eliminate","sep":"non separabile","ex":"I need to get rid of these old clothes."},{"pv":"to get back into","it":"riprendere (un'attività)","eq":"to return to","sep":"non separabile","ex":"I want to get back into running."},{"pv":"to set up","it":"allestire, organizzare, montare","eq":"to arrange, to prepare","sep":"separabile","ex":"They set up the room for the party. / They set it up."},{"pv":"to run out of","it":"rimanere senza, esaurire","eq":"to finish, to use up","sep":"non separabile","ex":"We ran out of milk."},{"pv":"to pick up","it":"raccogliere","eq":"to collect, to gather","sep":"separabile","ex":"Pick up your toys. / Pick them up."},{"pv":"to turn down","it":"abbassare (il volume)","eq":"to lower, to reduce","sep":"separabile","ex":"Turn down the music. / Turn it down."},{"pv":"to turn up","it":"alzare (il volume) · anche: presentarsi, arrivare","eq":"to raise, to increase · to show up, to arrive","sep":"separabile","ex":"Turn up the music. / Turn it up. · She turned up late for the meeting."},{"pv":"to look after","it":"prendersi cura di","eq":"to take care of, to care for","sep":"non separabile","ex":"She looks after the cats."},{"pv":"to hang out","it":"passare tempo insieme, uscire con","eq":"to spend time together","sep":"non separabile","ex":"We hung out at the beach."},{"pv":"to put off","it":"rimandare","eq":"to postpone","sep":"separabile","ex":"They put off the meeting. / They put it off."},{"pv":"to find out","it":"scoprire, venire a sapere","eq":"to discover","sep":"separabile","ex":"I found out the truth."},{"pv":"to back down","it":"tirarsi indietro, cedere","eq":"to withdraw, to give in","sep":"non separabile","ex":"I never back down from a challenge."},{"pv":"to come across","it":"imbattersi in; dare l'impressione di essere","eq":"to find by chance, to seem","sep":"non separabile","ex":"I came across an old photo. / He comes across as shy."},{"pv":"to come upon","it":"imbattersi in","eq":"to encounter","sep":"non separabile","ex":"We came upon a little village."},{"pv":"to get up","it":"alzarsi (dal letto)","eq":"to rise","sep":"non separabile","ex":"I get up at seven every morning."},{"pv":"to let down","it":"deludere","eq":"to disappoint","sep":"separabile","ex":"Don't worry, I won't let you down. / He let us down."},{"pv":"to let in","it":"far entrare","eq":"to admit","sep":"separabile","ex":"She opened the door and let me in."},{"pv":"to look for","it":"cercare","eq":"to search for, to seek","sep":"non separabile","ex":"I'm looking for my keys."},{"pv":"to rely on","it":"contare su, fare affidamento su","eq":"to depend on, to trust","sep":"non separabile","ex":"You can rely on me."},{"pv":"to take care of","it":"prendersi cura di, occuparsi di","eq":"to look after, to handle","sep":"non separabile","ex":"She takes care of the kids."},{"pv":"to be off","it":"1) essere libero (dal lavoro) 2) essere via/assente 3) (cibo) andato a male 4) spento 5) andarsene","eq":"1) to be free 2) to be away 3) to be spoiled 4) to be switched off 5) to leave","sep":"non separabile","ex":"I'm off on Mondays. · She's off sick today. · This milk is off. · The lights are off. · Right, I'm off!"},{"pv":"to make fun of","it":"prendere in giro, deridere qualcuno","eq":"to mock, to ridicule","sep":"non separabile","ex":"Don't make fun of him, it's not nice."},{"pv":"to pick on","it":"prendersela con qualcuno in modo cattivo e continuo","eq":"to bully, to target","sep":"non separabile","ex":"Tahani picks on Eleanor because she is jealous of her."},{"pv":"to play a trick on","it":"fare uno scherzo a qualcuno","eq":"to prank","sep":"non separabile","ex":"They played a trick on their teacher."},{"pv":"to set off","it":"partire, mettersi in cammino · anche: far scattare (un allarme)","eq":"to depart, to leave · to trigger (an alarm)","sep":"non separabile","ex":"Toma set off toward the dragon's cave. · The loud noise set off the car alarm."},{"pv":"to light up","it":"illuminarsi, accendersi · anche: illuminarsi (il viso) di gioia","eq":"to become bright · (of a face) to brighten with joy","sep":"separabile","ex":"Her face lit up when she saw the gift. / They lit up the Christmas tree. / They lit it up."},{"pv":"to gobble up","it":"divorare, mangiare avidamente · anche: accaparrarsi (risorse, terreno)","eq":"to eat greedily · to consume quickly","sep":"separabile","ex":"The dog gobbled up all the food. / He gobbled it up in seconds."}],"schemi":[{"title":"Promemoria — i miei errori ricorrenti","note":"Aggiungeremo altri punti qui man mano, senza farne regole a parte.","cols":["Sbagliato","Corretto","Perché"],"rows":[["she doesn't very happy","she isn't very happy","Con l'aggettivo dopo essere → to be (isn't), mai doesn't."],["she doesn't give up (in quel momento)","she won't give up","Rifiuto/decisione del momento → won't, più naturale del semplice presente."],["When only five minutes left…","With only five minutes left… / When only five minutes are left…","with + nome (senza verbo) ambienta una situazione; when è congiunzione e vuole soggetto+verbo (are/remain)."],["not confident to speak English","not confident about speaking English","Dopo confident si usa about / in + -ing (o + nome), non to + verbo: confident about speaking, confident in your abilities."],["I let someone else speaks","I let someone else speak","Dopo let (+ persona) il verbo va alla forma BASE, senza -s: let him go, let her speak, let them decide."],["to set the rules (nel senso di fissarle in mente)","to reinforce / to cement the rules","'Fissare' è un falso amico: to set = stabilire/fissare regole nuove (come un arbitro); per 'fissare in memoria' usa reinforce, cement o consolidate."],["listen to someone to talk","listen to someone talk / talking","Dopo i verbi di percezione (listen to, watch, hear) + persona, il verbo va alla forma BASE (o -ing), mai to + verbo: listen to someone talk, watch her play, hear them sing. Stesso schema di let."],["I study so that later I forget everything","I study for hours, only to forget everything later","'Per poi' con risultato deludente/ironico (non voluto) si traduce con only to + infinito, non so that: so that indica uno scopo voluto (affinché), il contrario di quello che intendevi."],["Toma lives in a quiet mountain village, he is a baker","Toma lives in a quiet mountain village. He is a baker","Virgola a catena: due frasi complete (soggetto+verbo) non si uniscono con una sola virgola. Serve un punto, un punto e virgola, oppure una congiunzione (and/but)."],["Toma at that point makes a plan","At that point, Toma makes a plan","Le frasi avverbiali complete (every night, at that point, in the end…) stanno meglio a inizio o fine frase; messe tra soggetto e verbo suonano innaturali — diverso dagli avverbi singoli come always/often/never, che invece vanno bene lì."]]},{"title":"Tempi verbali — quando usarli","note":"Chiave: azione CONCLUSA → Past Simple (She lived in Italy = ora non più). Azione ANCORA in corso → Present Perfect (I have lived here for 5 years = ci vivo ancora). L'italiano 'da…' col presente → in inglese Present Perfect.","cols":["Tempo","Quando si usa","Esempio"],"rows":[["Present Simple","routine, abitudini, cose sempre vere, trama di un film\nalways, usually, often, sometimes, never, every day","I sometimes go to the gym."],["Past Simple","azioni concluse nel passato, abitudini passate, antefatto di un film\nyesterday, ago, last week, in 2010","She lived in Italy for several years."],["Present Perfect","azione iniziata nel passato e ancora in corso / legata a ora\nfor, since, just, already, yet, ever, never","I have lived here for 5 years. · I have known her since 2010."],["Present Perfect Continuous","come il Present Perfect, ma mette l'accento sulla DURATA/il processo ancora in corso, o su un'azione appena finita con un effetto visibile ora\nfor, since, all day, lately","I've been studying English for several years. · I'm tired because I've been running."]]},{"title":"Present Perfect — quale paradigma? (2° vs 3°)","note":"Il Present Perfect vuole SEMPRE il 3° paradigma (participio passato), MAI il 2° (past simple). Con i verbi regolari sono uguali (-ed = -ed), per questo la differenza si nota solo con gli irregolari.","cols":["Verbo","1° (base)","2° (past simple)","3° (participio — Perfect)"],"rows":[["go","go","went","gone"],["see","see","saw","seen"],["do","do","did","done"],["write","write","wrote","written"],["eat","eat","ate","eaten"],["study (regolare)","study","studied","studied"]]},{"title":"Present Perfect (Continuous) — come si costruisce","note":"Present Perfect = fatto/risultato/quante volte. Present Perfect Continuous = processo/durata ancora sentito ora. Con for/since spesso sono intercambiabili (I've lived here for 5 years = I've been living here for 5 years).","cols":["Tempo","Costruzione","Esempio"],"rows":[["Present Perfect","have/has + 3° paradigma","I have studied. · She has gone. · They have written."],["Present Perfect Continuous","have/has + been + verbo-ing","I have been studying. · She has been working. · They have been waiting."]]},{"title":"Pronomi e possessivi","note":"Attenzione: its = possessivo (its name); it's = it is / it has.","cols":["Personale","Complemento","Agg. poss.","Pron. poss."],"rows":[["I","me","my","mine"],["you","you","your","yours"],["he","him","his","his"],["she","her","her","hers"],["it","it","its","its"],["we","us","our","ours"],["you","you","your","yours"],["they","them","their","theirs"]]},{"title":"Pronomi relativi (that / who / which)","note":"Puoi omettere il pronome solo in frasi informali, quando la relazione è chiara e non si perde il senso. Es.: The book I read last night was very interesting.","cols":["Pronome","= (it)","Si usa per","Note"],"rows":[["that","che","persone, animali, cose","info essenziale"],["who","che","persone","più formale"],["which","che","animali, cose",""]]},{"title":"One / ones (pronome)","note":"one / ones sostituisce un nome già detto, per non ripeterlo. one = singolare, ones = plurale.","cols":["Struttura","Esempio"],"rows":[["one (sing.)","Have you got a pen? — Yes, I've got one."],["ones (plur.)","Can I have some clean ones?"],["Which one? / Which ones?","Which one do you want?"],["this / that one · the one…","That one. / The one opposite the bank."],["the + agg. + one/ones","I like the brown one. / the other ones"],["a/an + agg. + one","This cup is dirty. Can I have a clean one?"],["some + agg. + ones","Can I have some clean ones?"]]},{"title":"Some / Any — guarda la frase","note":"Es.: I have some friends · I don't have any money · Do you have any friends? · Would you like some tea?","cols":["Frase","Parola"],"rows":[["affermativa","some"],["negativa","any"],["domanda","any"],["offerta / richiesta","some"]]},{"title":"Avere freddo/fame/paura… → to be, non to have","note":"In italiano questi stati fisici, emotivi o l'età si esprimono con avere; in inglese con il verbo essere (to be) + aggettivo o numero. Attenzione a 'cold': come aggettivo = freddo (I'm cold), come nome = raffreddore (I have a cold, con l'articolo).","cols":["Italiano","NON dire","Si dice"],"rows":[["avere freddo","I have cold","I'm cold"],["avere caldo","I have hot","I'm hot"],["avere fame","I have hungry","I'm hungry"],["avere sete","I have thirsty","I'm thirsty"],["avere paura","I have afraid","I'm afraid"],["avere sonno","I have sleepy","I'm sleepy"],["avere ragione","I have right","I'm right"],["avere torto","I have wrong","I'm wrong"],["avere fretta","I have hurry","I'm in a hurry"],["avere … anni (età)","I have 30 years","I'm 30 (years old)"]]},{"title":"Much / Many · a few / a little — guarda la quantità","note":"a few / a little: ce n'è, anche se poco = tono +.   few / little: quasi niente = tono -.","cols":["Significato","Numerabili","Non numerabili"],"rows":[["tanti / molti","many\nmany friends","much\nmuch time"],["alcuni / un po'","a few\na few friends","a little\na little time"]]},{"title":"Until, yet, already, just, never, ever, enough — dove vanno nella frase","note":"Regola generale: questi avverbi/congiunzioni si mettono TRA il soggetto e il verbo, cioè subito dopo l'ausiliare (have/has) o dopo il verbo essere — mai prima del soggetto. enough e until fanno eccezione a questa posizione (vedi righe sotto).","cols":["Parola","Tipo","Dove va","Esempio"],"rows":[["already","avverbio (Present Perfect, frasi affermative)","tra ausiliare e verbo · oppure a fine frase per enfasi","I have already finished. / I've finished already."],["just","avverbio (Present Perfect, azione appena successa)","subito dopo l'ausiliare have/has, prima del verbo","I have just finished. · She has just arrived."],["yet","avverbio (negative e domande)","sempre a FINE frase","I haven't finished yet. · Have you finished yet?"],["never","avverbio di frequenza (negazione forte)","tra soggetto e verbo (dopo l'ausiliare o il verbo essere)","I have never been to Paris. · She never goes out."],["ever","avverbio (domande, negative, superlativi)","tra ausiliare e verbo","Have you ever been to Paris? · It's the best film I've ever seen."],["enough","avverbio/quantificatore — ECCEZIONE di posizione","DOPO l'aggettivo o l'avverbio; PRIMA del nome","It's not good enough. (agg + enough) · I don't have enough time. (enough + nome)"],["until","congiunzione/preposizione — ECCEZIONE, non è un avverbio di frase","congiunzione: + soggetto + verbo (mai + to + infinito) · preposizione: + nome/momento","I'll wait until you arrive. · I'll carry on studying until I can speak fluently. · Open until 6pm."]]},{"title":"Frasi per chat di scambio linguistico (language exchange)","note":"Frasi pronte da usare nelle chat dell'app di scambio linguistico: saluto, proporre lo scambio, rompere il ghiaccio, parlare del tuo inglese, chiudere la conversazione.","cols":["Situazione","Frase (EN)","Traduzione"],"rows":[["Saluto","Hi! / Hello! How are you?","Ciao! Come stai?"],["Proporre lo scambio","Would you like to do a language exchange?","Ti va di fare uno scambio linguistico?"],["Proporre lo scambio","I can help you with Italian and you can help me with English.","Io posso aiutarti con l'italiano e tu con l'inglese."],["Proporre lo scambio","That works for me! / That sounds great to me.","Per me va bene! / Mi sembra un'ottima idea."],["Rompere il ghiaccio","Where are you from? / Which city do you live in?","Di dove sei? / In che città vivi?"],["Rompere il ghiaccio","Have you ever been to Italy?","Sei mai stato/a in Italia?"],["Rompere il ghiaccio","What do you do for a living?","Che lavoro fai?"],["Parlare del tuo inglese","I'm studying English on my own.","Sto studiando inglese da autodidatta."],["Parlare del tuo inglese","I'd like to be able to speak it so I can travel freely.","Vorrei riuscire a parlarlo per viaggiare liberamente."],["Parlare del tuo inglese","It's going well, thanks! I'm improving little by little.","Va bene, grazie! Sto migliorando poco a poco."],["Parlare del tuo inglese","My English isn't very good yet, but I'm getting better.","Il mio inglese non è ancora un granché, ma sto migliorando."],["Ringraziare","Thank you for your message! / Thanks for writing to me!","Grazie per il tuo messaggio!"],["Chiudere la conversazione","Sorry, I have to go now — let's talk another time. See you soon!","Scusa, devo andare — ci sentiamo un'altra volta. A presto!"]]}],"irregolari":[{"en":"be","it":"essere","past":"was / were","pp":"been"},{"en":"become","it":"diventare","past":"became","pp":"become"},{"en":"begin","it":"iniziare","past":"began","pp":"begun"},{"en":"bend","it":"piegare","past":"bent","pp":"bent"},{"en":"bet","it":"scommettere","past":"bet","pp":"bet"},{"en":"bind","it":"legare","past":"bound","pp":"bound"},{"en":"bite","it":"mordere","past":"bit","pp":"bitten"},{"en":"bleed","it":"sanguinare","past":"bled","pp":"bled"},{"en":"blow","it":"soffiare","past":"blew","pp":"blown"},{"en":"break","it":"rompere","past":"broke","pp":"broken"},{"en":"breed","it":"allevare","past":"bred","pp":"bred"},{"en":"bring","it":"portare","past":"brought","pp":"brought"},{"en":"broadcast","it":"trasmettere","past":"broadcast","pp":"broadcast"},{"en":"build","it":"costruire","past":"built","pp":"built"},{"en":"burn","it":"bruciare","past":"burnt / burned","pp":"burnt / burned"},{"en":"burst","it":"scoppiare","past":"burst","pp":"burst"},{"en":"buy","it":"comprare","past":"bought","pp":"bought"},{"en":"catch","it":"prendere, afferrare","past":"caught","pp":"caught"},{"en":"choose","it":"scegliere","past":"chose","pp":"chosen"},{"en":"come","it":"venire","past":"came","pp":"come"},{"en":"cost","it":"costare","past":"cost","pp":"cost"},{"en":"creep","it":"strisciare","past":"crept","pp":"crept"},{"en":"cut","it":"tagliare","past":"cut","pp":"cut"},{"en":"deal","it":"trattare, gestire","past":"dealt","pp":"dealt"},{"en":"dig","it":"scavare","past":"dug","pp":"dug"},{"en":"do","it":"fare","past":"did","pp":"done"},{"en":"draw","it":"disegnare, tirare","past":"drew","pp":"drawn"},{"en":"dream","it":"sognare","past":"dreamt / dreamed","pp":"dreamt / dreamed"},{"en":"drink","it":"bere","past":"drank","pp":"drunk"},{"en":"drive","it":"guidare","past":"drove","pp":"driven"},{"en":"eat","it":"mangiare","past":"ate","pp":"eaten"},{"en":"fall","it":"cadere","past":"fell","pp":"fallen"},{"en":"feed","it":"nutrire","past":"fed","pp":"fed"},{"en":"feel","it":"sentire (percezione)","past":"felt","pp":"felt"},{"en":"fight","it":"combattere","past":"fought","pp":"fought"},{"en":"find","it":"trovare","past":"found","pp":"found"},{"en":"flee","it":"fuggire","past":"fled","pp":"fled"},{"en":"fly","it":"volare","past":"flew","pp":"flown"},{"en":"forbid","it":"proibire","past":"forbade","pp":"forbidden"},{"en":"forget","it":"dimenticare","past":"forgot","pp":"forgotten"},{"en":"forgive","it":"perdonare","past":"forgave","pp":"forgiven"},{"en":"freeze","it":"congelare, gelare","past":"froze","pp":"frozen"},{"en":"get","it":"ottenere, diventare","past":"got","pp":"got / gotten"},{"en":"give","it":"dare","past":"gave","pp":"given"},{"en":"go","it":"andare","past":"went","pp":"gone"},{"en":"grow","it":"crescere","past":"grew","pp":"grown"},{"en":"hang","it":"appendere","past":"hung","pp":"hung"},{"en":"have","it":"avere","past":"had","pp":"had"},{"en":"hear","it":"sentire (udire)","past":"heard","pp":"heard"},{"en":"hide","it":"nascondere","past":"hid","pp":"hidden"},{"en":"hit","it":"colpire","past":"hit","pp":"hit"},{"en":"hold","it":"tenere","past":"held","pp":"held"},{"en":"hurt","it":"ferire, far male","past":"hurt","pp":"hurt"},{"en":"keep","it":"tenere, mantenere","past":"kept","pp":"kept"},{"en":"kneel","it":"inginocchiarsi","past":"knelt / kneeled","pp":"knelt / kneeled"},{"en":"know","it":"sapere, conoscere","past":"knew","pp":"known"},{"en":"lay","it":"posare, stendere","past":"laid","pp":"laid"},{"en":"lead","it":"guidare, condurre","past":"led","pp":"led"},{"en":"lean","it":"appoggiarsi","past":"leant / leaned","pp":"leant / leaned"},{"en":"leap","it":"saltare","past":"leapt / leaped","pp":"leapt / leaped"},{"en":"learn","it":"imparare","past":"learnt / learned","pp":"learnt / learned"},{"en":"leave","it":"lasciare, partire","past":"left","pp":"left"},{"en":"lend","it":"prestare","past":"lent","pp":"lent"},{"en":"let","it":"lasciare, permettere","past":"let","pp":"let"},{"en":"lie (sdraiarsi)","it":"giacere, sdraiarsi","past":"lay","pp":"lain"},{"en":"light","it":"accendere","past":"lit / lighted","pp":"lit / lighted"},{"en":"lose","it":"perdere","past":"lost","pp":"lost"},{"en":"make","it":"fare, creare","past":"made","pp":"made"},{"en":"mean","it":"significare","past":"meant","pp":"meant"},{"en":"meet","it":"incontrare","past":"met","pp":"met"},{"en":"mistake","it":"sbagliare, confondere","past":"mistook","pp":"mistaken"},{"en":"overcome","it":"superare","past":"overcame","pp":"overcome"},{"en":"pay","it":"pagare","past":"paid","pp":"paid"},{"en":"put","it":"mettere","past":"put","pp":"put"},{"en":"quit","it":"smettere, lasciare","past":"quit / quitted","pp":"quit / quitted"},{"en":"read","it":"leggere","past":"read (pron. \"red\")","pp":"read (pron. \"red\")"},{"en":"ride","it":"cavalcare, andare (in bici/moto)","past":"rode","pp":"ridden"},{"en":"ring","it":"suonare (campanello)","past":"rang","pp":"rung"},{"en":"rise","it":"alzarsi, sorgere","past":"rose","pp":"risen"},{"en":"run","it":"correre","past":"ran","pp":"run"},{"en":"say","it":"dire","past":"said","pp":"said"},{"en":"see","it":"vedere","past":"saw","pp":"seen"},{"en":"seek","it":"cercare","past":"sought","pp":"sought"},{"en":"sell","it":"vendere","past":"sold","pp":"sold"},{"en":"send","it":"mandare","past":"sent","pp":"sent"},{"en":"set","it":"impostare, posizionare","past":"set","pp":"set"},{"en":"sew","it":"cucire","past":"sewed","pp":"sewn / sewed"},{"en":"shake","it":"scuotere","past":"shook","pp":"shaken"},{"en":"shine","it":"brillare","past":"shone / shined","pp":"shone / shined"},{"en":"shoot","it":"sparare","past":"shot","pp":"shot"},{"en":"show","it":"mostrare","past":"showed","pp":"shown / showed"},{"en":"shrink","it":"restringersi","past":"shrank / shrunk","pp":"shrunk / shrunken"},{"en":"shut","it":"chiudere","past":"shut","pp":"shut"},{"en":"sing","it":"cantare","past":"sang","pp":"sung"},{"en":"sink","it":"affondare","past":"sank","pp":"sunk"},{"en":"sit","it":"sedersi","past":"sat","pp":"sat"},{"en":"sleep","it":"dormire","past":"slept","pp":"slept"},{"en":"slide","it":"scivolare","past":"slid","pp":"slid"},{"en":"speak","it":"parlare","past":"spoke","pp":"spoken"},{"en":"speed","it":"affrettarsi, andare veloce","past":"sped / speeded","pp":"sped / speeded"},{"en":"spell","it":"sillabare, compitare","past":"spelt / spelled","pp":"spelt / spelled"},{"en":"spend","it":"spendere, trascorrere","past":"spent","pp":"spent"},{"en":"spill","it":"versare","past":"spilt / spilled","pp":"spilt / spilled"},{"en":"spin","it":"girare, filare","past":"spun","pp":"spun"},{"en":"split","it":"dividere, spaccare","past":"split","pp":"split"},{"en":"spread","it":"spargere, diffondere","past":"spread","pp":"spread"},{"en":"spring","it":"balzare","past":"sprang","pp":"sprung"},{"en":"stand","it":"stare in piedi","past":"stood","pp":"stood"},{"en":"steal","it":"rubare","past":"stole","pp":"stolen"},{"en":"stick","it":"attaccare, incollare","past":"stuck","pp":"stuck"},{"en":"sting","it":"pungere","past":"stung","pp":"stung"},{"en":"stink","it":"puzzare","past":"stank / stunk","pp":"stunk"},{"en":"strike","it":"colpire, scioperare","past":"struck","pp":"struck"},{"en":"swear","it":"giurare, imprecare","past":"swore","pp":"sworn"},{"en":"sweep","it":"spazzare","past":"swept","pp":"swept"},{"en":"swim","it":"nuotare","past":"swam","pp":"swum"},{"en":"swing","it":"dondolare","past":"swung","pp":"swung"},{"en":"take","it":"prendere","past":"took","pp":"taken"},{"en":"teach","it":"insegnare","past":"taught","pp":"taught"},{"en":"tear","it":"strappare","past":"tore","pp":"torn"},{"en":"tell","it":"dire, raccontare","past":"told","pp":"told"},{"en":"think","it":"pensare","past":"thought","pp":"thought"},{"en":"throw","it":"lanciare","past":"threw","pp":"thrown"},{"en":"understand","it":"capire","past":"understood","pp":"understood"},{"en":"wake","it":"svegliarsi, svegliare","past":"woke","pp":"woken"},{"en":"wear","it":"indossare","past":"wore","pp":"worn"},{"en":"weep","it":"piangere","past":"wept","pp":"wept"},{"en":"win","it":"vincere","past":"won","pp":"won"},{"en":"wind","it":"avvolgere, caricare","past":"wound","pp":"wound"},{"en":"write","it":"scrivere","past":"wrote","pp":"written"}],"catOrder":["Verbi & tempi","Nomi, articoli & quantità","Pronomi & possessivi","Aggettivi & confronti","Preposizioni","Parole che si confondono","Sintassi & frasi","Extra & lessico"]};
